         <div className="flex space-x-2">
            <input 
              type="text" 
              placeholder="example.com"
              className="flex-1 px-4 py-2 rounded-lg border border-orange-200 text-sm focus:outline-none focus:ring-2 focus:ring-orange-500"
            />
            <button className="bg-orange-600 text-white px-6 py-2 rounded-lg text-sm font-bold hover:bg-orange-700">
              Add Domain
