export default Integration;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import { View, Document, WidgetSettings } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'OmniAssistant',
    welcomeMessage: 'Hello! How can I help you with our product today?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const addDocument = (doc: Document) => {
    setDocuments(prev => [...prev, doc]);
  };

  const deleteDocument = (id: string) => {
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard />;
      case View.KNOWLEDGE_BASE:
        return <KnowledgeBase documents={documents} onAddDocument={addDocument} onDeleteDocument={deleteDocument} />;
      case View.WIDGET_CONFIG:
        return <WidgetPreview settings={settings} setSettings={setSettings} />;
      case View.INTEGRATION:
        return <Integration />;
      case View.ANALYTICS:
        return (
          <div className="flex flex-col items-center justify-center h-full text-gray-400 py-20">
            <i className="fas fa-history text-6xl mb-4"></i>
            <h2 className="text-xl font-bold">Conversation Logs</h2>
            <p>You haven't had any conversations yet. Test your widget to see data here.</p>
          </div>
        );
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-8 z-10 shrink-0">
          <div className="flex items-center space-x-2">
            <h1 className="text-sm font-bold text-gray-500 uppercase tracking-widest">{currentView.replace('_', ' ')}</h1>
          </div>
          <div className="flex items-center space-x-4">
