import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message } from '../types';

interface Props {
  settings: WidgetSettings;
  userId: string;
}

const ChatWidget: React.FC<Props> = ({ settings, userId }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch('http://localhost:3001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input, userId, botName: settings.botName })
      });
      const data = await response.json();

      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: data.text, timestamp: Date.now() }]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Lỗi kết nối AI.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`fixed bottom-6 ${settings.position === 'right' ? 'right-6' : 'left-6'} z-[9999] font-sans`}>
      <button onClick={() => setIsOpen(!isOpen)} className="w-14 h-14 lg:w-16 lg:h-16 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-transform hover:scale-110" style={{ backgroundColor: settings.primaryColor }}>
        {isOpen ? <i className="fas fa-times"></i> : <i className="fas fa-comment-alt"></i>}
      </button>

      {isOpen && (
        <div className={`absolute bottom-20 ${settings.position === 'right' ? 'right-0' : 'left-0'} w-[calc(100vw-3rem)] sm:w-96 h-[500px] bg-white rounded-3xl shadow-2xl overflow-hidden border border-gray-100 flex flex-col`}>
          <div className="p-6 text-white" style={{ backgroundColor: settings.primaryColor }}>
            <h3 className="font-bold text-lg">{settings.botName}</h3>
            <p className="text-xs opacity-80">Online • Của doanh nghiệp bạn</p>
          </div>

          <div ref={scrollRef} className="flex-1 p-4 bg-gray-50 space-y-4 overflow-y-auto">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white text-gray-800 border'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
          </div>

          <div className="p-4 bg-white border-t">
            <div className="flex items-center space-x-2 bg-gray-100 p-2 rounded-2xl">
              <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSend()} placeholder="Hỏi gì đó..." className="flex-1 text-sm bg-transparent outline-none px-2" disabled={isLoading} />
              <button onClick={handleSend} className="text-blue-600 p-2"><i className="fas fa-paper-plane"></i></button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatWidget;

