import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings } from "../types";

// Khởi tạo dữ liệu mẫu nếu chưa có
const DB_KEY = 'omnichat_db_v1';

const getDB = () => {
  const data = localStorage.getItem(DB_KEY);
  return data ? JSON.parse(data) : { users: [], documents: [] };
};

const saveDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    const db = getDB();
    if (db.users.find((u: any) => u.email === email)) {
      return { success: false, message: 'Email này đã được đăng ký.' };
    }
    const newUser: User = {
      id: Math.random().toString(36).substring(2, 11),
      email,
      password,
      botSettings: {
        botName: 'Trợ lý AI',
        primaryColor: '#2563eb',
        welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
        position: 'right',
        avatarUrl: 'https://picsum.photos/100/100'
      }
    };
    db.users.push(newUser);
    saveDB(db);
    return { success: true, message: 'Đăng ký thành công!', user: newUser };
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    const db = getDB();
    const user = db.users.find((u: any) => u.email === email && u.password === password);
    if (user) {
      return { success: true, message: 'Đăng nhập thành công', user };
    }
    return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    const db = getDB();
    const userIndex = db.users.findIndex((u: any) => u.id === userId);
    if (userIndex !== -1) {
      db.users[userIndex].botSettings = settings;
      saveDB(db);
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    const db = getDB();
    return db.documents.filter((d: any) => d.userId === userId);
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    const db = getDB();
    const newDoc: Document = {
      id: Math.random().toString(36).substring(2, 11),
      userId,
      name,
      content,
      type,
      status: 'indexed',
      createdAt: Date.now()
    };
    db.documents.push(newDoc);
    saveDB(db);
    return newDoc;
  },

  deleteDocument: async (id: string) => {
    const db = getDB();
    db.documents = db.documents.filter((d: any) => d.id !== id);
    saveDB(db);
  },

  // --- AI CHAT ---
  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return "Vui lòng cấu hình API_KEY để sử dụng AI.";

    const db = getDB();
    const userDocs = db.documents.filter((d: any) => d.userId === userId);
    const context = userDocs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');

    const ai = new GoogleGenAI({ apiKey });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau để hỗ trợ khách hàng: \n${context || "Không có tài liệu cụ thể. Hãy trả lời dựa trên kiến thức chung một cách chuyên nghiệp."}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: message }] }],
        config: { systemInstruction }
      });
      return response.text || "Xin lỗi, tôi không thể trả lời lúc này.";
    } catch (e) {
      console.error(e);
      return "Lỗi kết nối AI.";
    }
  }
};

import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Hãy đăng nhập.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Có lỗi xảy ra trong quá trình xử lý.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-50 p-4 font-sans">
      <div className="max-w-md w-full space-y-8 bg-white p-8 lg:p-10 rounded-3xl shadow-xl border border-gray-100 animate-in fade-in zoom-in duration-300">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-4 shadow-lg shadow-blue-100">
            <i className="fas fa-rocket"></i>
          </div>
          <h2 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tight">
            {isRegister ? 'Tạo tài khoản SaaS' : 'Đăng nhập OmniChat'}
          </h2>
          <p className="mt-2 text-sm text-gray-500">Nền tảng AI Chatbot cho doanh nghiệp.</p>
        </div>

        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-4 rounded-xl text-xs font-bold border ${error.includes('thành công') ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'}`}>
              <i className={`fas ${error.includes('thành công') ? 'fa-check-circle' : 'fa-exclamation-circle'} mr-2`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Email doanh nghiệp</label>
              <input 
                type="email" 
                required 
                value={email} 
                onChange={(e) => setEmail(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm" 
                placeholder="name@company.com" 
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Mật khẩu</label>
              <input 
                type="password" 
                required 
                value={password} 
                onChange={(e) => setPassword(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm" 
                placeholder="••••••••" 
              />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full flex justify-center py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-blue-200 active:scale-[0.98]"
          >
            {isLoading ? <i className="fas fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào trang quản trị')}
          </button>
        </form>

        <div className="text-center pt-2">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }} 
            className="text-xs font-bold text-blue-600 hover:text-blue-800 transition-colors"
          >
            {isRegister ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký dùng thử'}
          </button>
        </div>

        <div className="pt-6 border-t border-gray-100 mt-6 flex justify-center space-x-4">
           <div className="text-[10px] text-gray-400 flex items-center">
             <i className="fas fa-shield-alt mr-1"></i> Data Encryption
           </div>
           <div className="text-[10px] text-gray-400 flex items-center">
             <i className="fas fa-cloud mr-1"></i> Cloud SaaS
           </div>
        </div>
      </div>
    </div>
  );
};

