    if (savedUserId && savedUserEmail) {
      // Vì là mock service, ta chỉ cần set lại state
      // Trong thực tế sẽ gọi API verify token
      const db = JSON.parse(localStorage.getItem('omnichat_db_v1') || '{"users":[]}');
      const user = db.users.find((u: any) => u.id === savedUserId);
      if (user) {
        handleLoginSuccess(user);
      }
    }
  }, []);

