                <Area type="monotone" dataKey="solved" stroke="#10b981" fill="transparent" strokeWidth={3} strokeDasharray="5 5" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
               <i className="fas fa-chart-bar text-5xl mb-4 opacity-20"></i>
               <p className="text-sm font-bold">Chưa có dữ liệu cho giai đoạn này</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import Login from './components/Login';
import { View, Document, WidgetSettings, User } from './types';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    if (savedUserId) {
      const db = JSON.parse(localStorage.getItem('omnichat_db_v1') || '{"users":[]}');
      const user = db.users.find((u: any) => u.id === savedUserId);
      if (user) handleLoginSuccess(user);
    }
  }, []);

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  if (!isLoggedIn) return <Login onLogin={handleLoginSuccess} />;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50 relative font-sans text-gray-900">
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-100 flex items-center justify-between px-4 lg:px-8 z-30 shrink-0 shadow-sm">
          <div className="flex items-center space-x-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-gray-400 hover:bg-gray-100 rounded-xl transition-colors">
              <i className="fas fa-bars text-lg"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">
                {currentView.replace('_', ' ')}
              </h1>
              <p className="text-xs font-bold text-gray-800 hidden sm:block">Hệ thống quản trị OmniChat</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <div className="flex items-center bg-gray-50 text-gray-700 px-3 py-1.5 rounded-xl border border-gray-100">
              <i className={`fas ${currentUser?.role === 'master' ? 'fa-crown text-yellow-500' : 'fa-user text-blue-400'} mr-2`}></i>
              <span className="text-xs font-bold truncate max-w-[150px]">{currentUser?.email}</span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 max-w-7xl mx-auto w-full scroll-smooth">
          {currentView === View.DASHBOARD && <Dashboard user={currentUser!} />}
          {currentView === View.KNOWLEDGE_BASE && (
            <KnowledgeBase 
              userId={currentUser!.id}
              documents={documents} 
              onAddDocument={addDocument} 
              onDeleteDocument={deleteDocument} 
            />
          )}
          {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
          {currentView === View.INTEGRATION && <Integration userId={currentUser!.id} />}
          {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
          {currentView === View.CUSTOMER_MANAGEMENT && (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 text-center py-20">
              <i className="fas fa-user-friends text-6xl mb-4"></i>
              <h2 className="text-xl font-bold">Danh sách khách hàng</h2>
              <p className="mt-2 max-w-xs">Chức năng quản lý chi tiết từng tài khoản khách hàng đang được hoàn thiện.</p>
            </div>
          )}
        </div>

        {/* Chỉ hiển thị chat preview nếu không phải Master account đang xem tổng quan */}
        {currentUser?.role !== 'master' && (
          <div className="fixed bottom-4 right-4 z-50">
            <ChatWidget settings={settings} userId={currentUser!.id} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

app.use(cors() as any);
app.use(express.json() as any);

const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ 
      users: [
        { id: 'admin', email: 'admin@omnichat.io', password: '123456', botSettings: { botName: 'OmniBot', primaryColor: '#2563eb', welcomeMessage: 'Xin chào!' } }
      ], 
      documents: [] 
    }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Đăng ký
app.post('/api/register', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();

  if (db.users.find((u: any) => u.email === email)) {
    return res.status(400).json({ success: false, message: 'Email đã tồn tại' });
  }

  const newUser = {
    id: Math.random().toString(36).substr(2, 9),
    email,
    password,
    botSettings: {
      botName: 'Trợ lý AI',
      primaryColor: '#2563eb',
      welcomeMessage: 'Chào mừng bạn đến với hỗ trợ trực tuyến!'
    }
  };

  db.users.push(newUser);
  saveDB(db);
  res.json({ success: true, user: { id: newUser.id, email: newUser.email } });
});

// API: Đăng nhập
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();
  const user = db.users.find((u: any) => u.email === email && u.password === password);

  if (user) {
    res.json({ success: true, user: { id: user.id, email: user.email, botSettings: user.botSettings } });
  } else {
    res.status(401).json({ success: false, message: 'Sai thông tin đăng nhập' });
  }
});

// API: Lấy tài liệu của riêng User
app.get('/api/documents/:userId', (req, res) => {
  const db = getDB();
  const userDocs = db.documents.filter((d: any) => d.userId === req.params.userId);
  res.json(userDocs);
});

// API: Lưu cấu hình Widget cho User
app.post('/api/settings/:userId', (req, res) => {
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === req.params.userId);
  if (userIndex !== -1) {
    db.users[userIndex].botSettings = req.body;
    saveDB(db);
    res.json({ success: true });
  } else {
    res.status(404).json({ success: false });
  }
});

// API: Thêm tài liệu văn bản (có userId)
app.post('/api/documents/text', (req, res) => {
  const { name, content, userId } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp (có userId)
// Fixed TypeScript type mismatch error by explicitly casting request and response to any
app.post('/api/documents/upload', upload.single('file'), (req: any, res: any) => {
  const file = (req as any).file;
  const { userId } = req.body;
  if (!file || !userId) return res.status(400).send('Missing file or userId.');

  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name: file.originalname,
    content: content,
    path: file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat AI (Chỉ lấy tài liệu của userId đó)
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName } = req.body;
  const db = getDB();

  if (!process.env.API_KEY) return res.status(500).json({ error: "Missing API KEY" });

  // Strictly adhering to GoogleGenAI initialization guidelines using process.env.API_KEY directly
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Phân tách dữ liệu: Chỉ lấy tài liệu của người đang chat
  const context = db.documents
    .filter((d: any) => d.userId === userId)
    .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`)
    .join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau để hỗ trợ khách hàng: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction }
    });
    // Extract text directly from the response object as per property access guidelines
    res.json({ text: response.text });
  } catch (error) {
    res.status(500).json({ error: "AI Error" });
  }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import { GoogleGenAI } from "@google/genai";
import { Document } from "../types";

// Hàm khởi tạo AI (Lấy từ môi trường hoặc bạn có thể dán trực tiếp key vào đây nếu test local)
const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY không tồn tại. Vui lòng thiết lập biến môi trường hoặc file .env");
  }
  // Use named parameter and direct process.env.API_KEY access as per guidelines
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const getChatResponse = async (
  userInput: string,
  history: { role: 'user' | 'model', parts: { text: string }[] }[],
  knowledgeBase: Document[],
  botName: string
): Promise<string> => {
  const ai = getAIClient();

  // Tổng hợp kiến thức từ kho tài liệu đã upload
  const context = knowledgeBase
    .filter(doc => doc.status === 'indexed')
    .map(doc => `[Tài liệu: ${doc.name}]\n${doc.content}`)
    .join('\n\n');

  // CHỈNH SỬA TẠI ĐÂY: Thay đổi "tính cách" và "quy tắc" của Bot
  const systemInstruction = `
    Bạn là một trợ lý hỗ trợ khách hàng chuyên nghiệp tên là "${botName}". 
    Nhiệm vụ của bạn là trả lời các câu hỏi của khách hàng DỰA TRÊN ngữ cảnh kho kiến thức được cung cấp dưới đây.

    KHO KIẾN THỨC:
    ${context || "Hiện chưa có tài liệu nào. Hãy trả lời lịch sự rằng bạn đang cập nhật dữ liệu."}

    QUY TẮC PHẢN HỒI:
    1. Trả lời bằng ngôn ngữ mà khách hàng sử dụng (mặc định là Tiếng Việt).
    2. Nếu thông tin có trong Kho Kiến Thức, hãy sử dụng nó để trả lời chính xác.
    3. Nếu không có thông tin, hãy nói: "Xin lỗi, tôi chưa có thông tin về vấn đề này. Bạn có muốn kết nối với nhân viên hỗ trợ không?"
    4. Không tự bịa đặt thông tin nằm ngoài tài liệu.
    5. Sử dụng Markdown để trình bày câu trả lời đẹp mắt (list, bold...).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Bạn có thể đổi sang 'gemini-3-pro-preview' nếu cần xử lý phức tạp hơn
      contents: userInput,
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    // Access .text property directly from response
    return response.text || "Tôi gặp khó khăn khi xử lý câu hỏi này.";
  } catch (error) {
    console.error("Lỗi Gemini API:", error);
    return "Hệ thống AI đang bận, vui lòng thử lại sau giây lát.";
  }
};

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole } from "../types";

const DB_KEY = 'omnichat_db_v1';

const getDB = () => {
  const data = localStorage.getItem(DB_KEY);
  // Thêm tài khoản master mặc định nếu chưa có
  const defaultDB = { 
    users: [
      {
        id: 'master_root',
        email: 'master@omnichat.io',
        password: 'master123',
        role: 'master' as UserRole,
        createdAt: Date.now(),
        botSettings: { botName: 'Master AI', primaryColor: '#000000', welcomeMessage: 'Admin Mode', position: 'right', avatarUrl: '' }
      }
    ], 
    documents: [],
    chatLogs: []
  };
  return data ? JSON.parse(data) : defaultDB;
};

const saveDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    const db = getDB();
    if (db.users.find((u: any) => u.email === email)) {
      return { success: false, message: 'Email này đã được đăng ký.' };
    }
    const newUser: User = {
      id: Math.random().toString(36).substring(2, 11),
      email,
      password,
      role: 'user',
      createdAt: Date.now(),
      botSettings: {
        botName: 'Trợ lý AI',
        primaryColor: '#2563eb',
        welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
        position: 'right',
        avatarUrl: 'https://picsum.photos/100/100'
      }
    };
    db.users.push(newUser);
    saveDB(db);
    return { success: true, message: 'Đăng ký thành công!', user: newUser };
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    const db = getDB();
    const user = db.users.find((u: any) => u.email === email && u.password === password);
    if (user) return { success: true, message: 'Đăng nhập thành công', user };
    return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    const db = getDB();
    return db.users.filter((u: User) => u.role !== 'master');
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    const db = getDB();
    const userIndex = db.users.findIndex((u: any) => u.id === userId);
    if (userIndex !== -1) {
      db.users[userIndex].botSettings = settings;
      saveDB(db);
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    const db = getDB();
    return db.documents.filter((d: any) => d.userId === userId);
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    const db = getDB();
    const newDoc: Document = {
      id: Math.random().toString(36).substring(2, 11),
      userId,
      name,
      content,
      type,
      status: 'indexed',
      createdAt: Date.now()
    };
    db.documents.push(newDoc);
    saveDB(db);
    return newDoc;
  },

  deleteDocument: async (id: string) => {
    const db = getDB();
    db.documents = db.documents.filter((d: any) => d.id !== id);
    saveDB(db);
  },

  // --- ANALYTICS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    const db = getDB();
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const now = Date.now();
    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  // --- AI CHAT ---
  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const db = getDB();
    const userDocs = db.documents.filter((d: any) => d.userId === userId);
    const context = userDocs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');

    // Using strictly required GoogleGenAI initialization pattern
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      // Accessing text property directly from the response object
      const reply = response.text || "Tôi không thể trả lời.";

      // LOGGING - Lưu lại lịch sử để thống kê
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveDB(db);

      return reply;
    } catch (e) {
      return "Lỗi AI.";
    }
  }
};

