import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import CustomerManagement from './components/CustomerManagement';
import Login from './components/Login';
import { View, Document, WidgetSettings, User } from './types';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    if (savedUserId) {
      const db = JSON.parse(localStorage.getItem('omnichat_db_v1') || '{"users":[]}');
      const user = db.users.find((u: any) => u.id === savedUserId);
      if (user) handleLoginSuccess(user);
    }
  }, []);

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    // Reset selection when changing views unless it's stats related
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) return <Login onLogin={handleLoginSuccess} />;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50 relative font-sans text-gray-900 antialiased">
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 z-30 shrink-0 shadow-sm">
          <div className="flex items-center space-x-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-gray-400 hover:bg-gray-100 rounded-xl transition-colors">
              <i className="fas fa-bars text-lg"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">
                {currentView.replace('_', ' ')}
              </h1>
              <p className="text-xs font-bold text-gray-800 hidden sm:block">
                {currentUser?.role === 'master' ? 'Hệ thống Quản trị Master' : 'Hệ thống Quản trị Doanh nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <div className="flex items-center bg-gray-50 text-gray-700 px-3 py-1.5 rounded-xl border border-gray-100">
              <i className={`fas ${currentUser?.role === 'master' ? 'fa-crown text-yellow-500' : 'fa-user text-blue-400'} mr-2`}></i>
              <span className="text-xs font-bold truncate max-w-[150px]">{currentUser?.email}</span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 max-w-7xl mx-auto w-full scroll-smooth">
          {currentView === View.DASHBOARD && (
            <Dashboard 
              user={currentUser!} 
              initialSelectedUser={selectedCustomerIdForStats} 
            />
          )}
          {currentView === View.KNOWLEDGE_BASE && (
            <KnowledgeBase 
              userId={currentUser!.id}
              documents={documents} 
              onAddDocument={addDocument} 
              onDeleteDocument={deleteDocument} 
            />
          )}
          {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
          {currentView === View.INTEGRATION && <Integration userId={currentUser!.id} />}
          {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
          {currentView === View.CUSTOMER_MANAGEMENT && currentUser?.role === 'master' && (
            <CustomerManagement onViewStats={handleViewCustomerStats} />
          )}
        </div>

        {currentUser?.role !== 'master' && (
          <div className="fixed bottom-4 right-4 z-50">
            <ChatWidget settings={settings} userId={currentUser!.id} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

