          <h2 className="text-2xl font-black text-gray-900">Thống kê hoạt động</h2>
          <p className="text-xs text-gray-500">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
