import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Hãy đăng nhập.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Có lỗi xảy ra trong quá trình xử lý.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-50 p-4 font-sans">
      <div className="max-w-md w-full space-y-8 bg-white p-8 lg:p-10 rounded-3xl shadow-xl border border-gray-100 animate-in fade-in zoom-in duration-300">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-4 shadow-lg shadow-blue-100">
            <i className="fa-solid fa-rocket"></i>
          </div>
          <h2 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tight">
            {isRegister ? 'Tạo tài khoản SaaS' : 'Đăng nhập OmniChat'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">Nền tảng AI Chatbot cho doanh nghiệp.</p>
        </div>

        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-4 rounded-xl text-xs font-bold border ${error.includes('thành công') ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'}`}>
              <i className={`fa-solid ${error.includes('thành công') ? 'fa-circle-check' : 'fa-circle-exclamation'} mr-2`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Email doanh nghiệp</label>
              <input 
                type="email" 
                required 
                value={email} 
                onChange={(e) => setEmail(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="name@company.com" 
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Mật khẩu</label>
              <input 
                type="password" 
                required 
                value={password} 
                onChange={(e) => setPassword(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="••••••••" 
              />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full flex justify-center py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-blue-200 active:scale-[0.98] items-center"
          >
            {isLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào trang quản trị')}
          </button>
        </form>

        <div className="text-center pt-2">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }} 
            className="text-xs font-bold text-blue-600 hover:text-blue-800 transition-colors"
          >
            {isRegister ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký dùng thử'}
          </button>
        </div>

        <div className="pt-6 border-t border-gray-100 mt-6 flex justify-center space-x-4">
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-shield-halved mr-1.5"></i> Data Encryption
           </div>
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-cloud mr-1.5"></i> Cloud SaaS
           </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
}

const ChatWidget: React.FC<Props> = ({ settings, userId }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await apiService.chat(userId, input, settings.botName);
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Hệ thống đang bận. Vui lòng thử lại sau.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`fixed bottom-6 ${settings.position === 'right' ? 'right-6' : 'left-6'} z-[9999] font-sans`}>
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className="w-14 h-14 lg:w-16 lg:h-16 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-all hover:scale-110 active:scale-95 duration-200" 
        style={{ backgroundColor: settings.primaryColor, boxShadow: `0 8px 24px -6px ${settings.primaryColor}` }}
      >
        {isOpen ? <i className="fa-solid fa-xmark"></i> : <i className="fa-solid fa-comment-dots"></i>}
      </button>

      {isOpen && (
        <div className={`absolute bottom-20 ${settings.position === 'right' ? 'right-0' : 'left-0'} w-[calc(100vw-3rem)] sm:w-96 h-[500px] bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-gray-100 flex flex-col animate-in slide-in-from-bottom-5 duration-300`}>
          <div className="p-6 text-white" style={{ backgroundColor: settings.primaryColor }}>
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center border border-white/30">
                <i className="fa-solid fa-robot"></i>
              </div>
              <div>
                <h3 className="font-black text-sm">{settings.botName}</h3>
                <p className="text-[10px] opacity-80 flex items-center font-bold">
                  <span className="w-1.5 h-1.5 bg-green-400 rounded-full mr-1.5 animate-pulse"></span>
                  Sẵn sàng hỗ trợ
                </p>
              </div>
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 p-4 bg-gray-50/50 space-y-4 overflow-y-auto scrollbar-thin scrollbar-thumb-gray-200">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3.5 rounded-2xl text-[13px] leading-relaxed shadow-sm font-medium ${
                  msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none'
                }`}>
                  <p className="whitespace-pre-wrap">{msg.text}</p>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm flex space-x-1.5">
                  <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-75"></div>
                  <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t border-gray-100">
            <div className="flex items-center space-x-2 bg-gray-50 p-1.5 rounded-2xl border border-gray-100 focus-within:ring-2 focus-within:ring-blue-500 focus-within:bg-white transition-all">
              <input 
                type="text" 
                value={input} 
                onChange={(e) => setInput(e.target.value)} 
                onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                placeholder="Nhập nội dung thắc mắc..." 
                className="flex-1 text-[13px] bg-transparent outline-none px-2 font-medium" 
                disabled={isLoading} 
              />
              <button 
                onClick={handleSend} 
                className="w-8 h-8 rounded-xl bg-blue-600 text-white flex items-center justify-center transition-transform active:scale-90"
                style={{ backgroundColor: settings.primaryColor }}
              >
                <i className="fa-solid fa-paper-plane text-xs"></i>
              </button>
            </div>
            <div className="text-[9px] text-center text-gray-400 mt-3 font-bold uppercase tracking-widest">
              Powered by OmniChat SaaS
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatWidget;

export enum View {
  DASHBOARD = 'dashboard',
  KNOWLEDGE_BASE = 'knowledge_base',
  WIDGET_CONFIG = 'widget_config',
  ANALYTICS = 'analytics',
  INTEGRATION = 'integration',
  DEPLOYMENT_GUIDE = 'deployment_guide',
  CUSTOMER_MANAGEMENT = 'customer_management',
  CHAT_HISTORY = 'chat_history'
}

export type UserRole = 'master' | 'user';

export interface Document {
  id: string;
  userId: string;
  name: string;
