                      <span className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full"><i className="fa-solid fa-check mr-1"></i>Đã xử lý</span>
                    ) : (
                      <span className="text-[10px] font-bold text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full"><i className="fa-solid fa-xmark mr-1"></i>Chưa rõ</span>
