    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-clock-rotate-left' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức AI', icon: 'fa-solid fa-brain' },
      { id: View.WIDGET_CONFIG, label: 'Tùy chỉnh Widget', icon: 'fa-solid fa-palette' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
