            <i className="fa-solid fa-clock-rotate-left text-blue-600 mr-3"></i>
            Lịch sử Trò chuyện
          </h2>
          <p className="text-base text-slate-500 font-medium mt-1">
            {isMaster ? 'Theo dõi toàn bộ hội thoại trên hệ thống.' : 'Xem lại các câu hỏi mà khách hàng đã gửi cho AI.'}
