      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List Column */}
        <div className={`lg:col-span-1 bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[650px] ${selectedLog ? 'hidden lg:flex' : 'flex'}`}>
