          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-white">
            {isLoading ? (
               <div className="flex justify-center p-10"><i className="fa-solid fa-circle-notch animate-spin text-blue-600 text-2xl"></i></div>
