import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

app.use(cors() as any);
app.use(express.json() as any);

const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ 
      users: [
        { id: 'admin', email: 'admin@omnichat.io', password: '123456', role: 'master', botSettings: { botName: 'OmniBot', primaryColor: '#2563eb', welcomeMessage: 'Xin chào!' } }
      ], 
      documents: [],
      chatLogs: []
    }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Lấy danh sách Users (Cho Master)
app.get('/api/users', (req, res) => {
  const db = getDB();
  // Trả về danh sách users (có thể lọc bỏ password nếu cần bảo mật cao hơn)
  res.json(db.users);
});

// API: Đăng ký
app.post('/api/register', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();

  if (db.users.find((u: any) => u.email === email)) {
    return res.status(400).json({ success: false, message: 'Email đã tồn tại' });
  }

  const newUser = {
    id: Math.random().toString(36).substr(2, 9),
    email,
    password,
    role: 'user',
    createdAt: Date.now(),
    botSettings: {
      botName: 'Trợ lý AI',
      primaryColor: '#2563eb',
      welcomeMessage: 'Chào mừng bạn đến với hỗ trợ trực tuyến!',
      position: 'right',
      avatarUrl: ''
    }
  };

  db.users.push(newUser);
  saveDB(db);
  res.json({ success: true, user: newUser });
});

// API: Đăng nhập
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();
  const user = db.users.find((u: any) => u.email === email && u.password === password);

  if (user) {
    res.json({ success: true, user });
  } else {
    res.status(401).json({ success: false, message: 'Sai thông tin đăng nhập' });
  }
});

// API: Đổi mật khẩu (User tự đổi)
app.post('/api/user/change-password', (req, res) => {
  const { userId, oldPassword, newPassword } = req.body;
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === userId);

  if (userIndex === -1) return res.status(404).json({ success: false, message: 'User không tồn tại' });

  if (db.users[userIndex].password !== oldPassword) {
    return res.status(400).json({ success: false, message: 'Mật khẩu cũ không đúng' });
  }

  db.users[userIndex].password = newPassword;
  saveDB(db);
  res.json({ success: true, message: 'Đổi mật khẩu thành công' });
});

// API: Reset mật khẩu (Admin thực hiện)
app.post('/api/admin/reset-password', (req, res) => {
  const { targetUserId, newPassword } = req.body;
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === targetUserId);

  if (userIndex === -1) return res.status(404).json({ success: false, message: 'User không tồn tại' });

  db.users[userIndex].password = newPassword;
  saveDB(db);
  res.json({ success: true, message: 'Reset mật khẩu thành công' });
});

// API: Xóa User (Admin thực hiện)
app.delete('/api/admin/users/:id', (req, res) => {
  const db = getDB();
  const targetId = req.params.id;

  // Xóa user
  const initialUserCount = db.users.length;
  db.users = db.users.filter((u: any) => u.id !== targetId);

  if (db.users.length === initialUserCount) {
    return res.status(404).json({ success: false, message: 'User không tồn tại' });
  }

  // Xóa các dữ liệu liên quan
  // 1. Xóa documents
  const userDocs = db.documents.filter((d: any) => d.userId === targetId);
  userDocs.forEach((doc: any) => {
    if (doc.path && fs.existsSync(doc.path)) {
      try { fs.unlinkSync(doc.path); } catch(e) {}
    }
  });
  db.documents = db.documents.filter((d: any) => d.userId !== targetId);

  // 2. Xóa chat logs
  db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetId);

  saveDB(db);
  res.json({ success: true, message: 'Xóa user thành công' });
});

// API: Lấy tài liệu của riêng User
app.get('/api/documents/:userId', (req, res) => {
  const db = getDB();
  const userDocs = db.documents.filter((d: any) => d.userId === req.params.userId);
  res.json(userDocs);
});

// API: Lưu cấu hình Widget cho User
app.post('/api/settings/:userId', (req, res) => {
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === req.params.userId);
  if (userIndex !== -1) {
    db.users[userIndex].botSettings = req.body;
    saveDB(db);
    res.json({ success: true });
  } else {
    res.status(404).json({ success: false });
  }
});

// API: Thêm tài liệu văn bản (có userId)
app.post('/api/documents/text', (req, res) => {
  const { name, content, userId } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp (có userId)
app.post('/api/documents/upload', upload.single('file') as any, (req: any, res: any) => {
  const file = (req as any).file;
  const { userId } = req.body;
  if (!file || !userId) return res.status(400).send('Missing file or userId.');

  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name: file.originalname,
    content: content,
    path: file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat AI (Chỉ lấy tài liệu của userId đó)
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName } = req.body;
  const db = getDB();

  if (!process.env.API_KEY) return res.status(500).json({ error: "Missing API KEY" });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = db.documents
    .filter((d: any) => d.userId === userId)
    .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`)
    .join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau để hỗ trợ khách hàng: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction }
    });

    const reply = response.text || "Tôi không thể trả lời.";

    // Lưu Log
    if (!db.chatLogs) db.chatLogs = [];
    const newLog = {
      id: Math.random().toString(36).substr(2, 9),
      userId,
      customerSessionId: 'anon-session',
      query: message,
      answer: reply,
      timestamp: Date.now(),
      tokens: message.length + reply.length,
      isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
    };
    db.chatLogs.push(newLog);
    saveDB(db);

    res.json({ text: reply });
  } catch (error) {
    res.status(500).json({ error: "AI Error" });
  }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole } from "../types";

const API_URL = 'http://localhost:3001/api';

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await res.json();
    } catch (e) {
      return { success: false, message: 'Lỗi kết nối server' };
    }
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await res.json();
    } catch (e) {
      return { success: false, message: 'Lỗi kết nối server' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      return await res.json();
    } catch (e) {
      return { success: false, message: 'Lỗi kết nối server' };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) return [];
      const users: User[] = await res.json();
      // Lọc bỏ tài khoản master gốc khỏi danh sách hiển thị
      return users.filter(u => u.id !== 'admin'); 
    } catch (e) {
      console.error("Error fetching users:", e);
      return [];
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      return await res.json();
    } catch (e) {
      return { success: false, message: 'Lỗi kết nối server' };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      return await res.json();
    } catch (e) {
      return { success: false, message: 'Lỗi kết nối server' };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    await fetch(`${API_URL}/settings/${userId}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(settings)
    });
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      return await res.json();
    } catch (e) {
      return [];
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    if (type === 'file') {
      // Đối với file, content ở đây là base64 hoặc raw string từ FileReader, 
      // Nhưng trong logic server.ts dùng multer cần FormData.
      // Để đơn giản hóa trong code này, chúng ta sẽ gửi text content
      // (Nếu muốn upload file binary thực sự cần sửa component KnowledgeBase để gửi File Object)
      // Tạm thời fallback về API text cho 'file' type nếu client chỉ gửi nội dung string
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      const doc = await res.json();
      return {...doc, type: 'file'}; // Hack type để hiển thị icon
    } else {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      return await res.json();
    }
  },

  deleteDocument: async (id: string) => {
    await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
  },

  // --- ANALYTICS & LOGS (Giữ logic cũ nhưng lấy dữ liệu mock từ server nếu cần, tạm thời giữ LocalStorage cho logs để giảm tải) ---
  // Lưu ý: Trong thực tế, nên chuyển cả Logs sang API. 
  // Để fix nhanh hiển thị Master, ta sẽ dùng API lấy tất cả user, nhưng logs có thể vẫn đang lưu LocalStorage.
  // Ở đây tôi sẽ update hàm getChatLogs để mock data hoặc lấy từ LocalStorage (vì server.ts chưa có endpoint get logs đầy đủ)

  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    // Tạm thời vẫn dùng LocalStorage cho ChatLogs để tránh mất dữ liệu cũ khi chưa migate xong DB
    // Nếu muốn full server, cần thêm API getLogs.
    // Logic dưới đây giả lập lấy từ LocalStorage như cũ
    const dbData = localStorage.getItem('omnichat_db_v1');
    const db = dbData ? JSON.parse(dbData) : { chatLogs: [] };
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    // Tạm thời vẫn lấy từ LocalStorage
    const dbData = localStorage.getItem('omnichat_db_v1');
    const db = dbData ? JSON.parse(dbData) : { chatLogs: [] };
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }
    return logs.sort((a, b) => b.timestamp - a.timestamp);
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    try {
      const res = await fetch(`${API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message, userId, botName })
      });
      const data = await res.json();

      // Đồng bộ log về LocalStorage để hiển thị ngay (Hybrid mode)
      const dbData = localStorage.getItem('omnichat_db_v1') || '{"chatLogs":[]}';
      const db = JSON.parse(dbData);
      if(!db.chatLogs) db.chatLogs = [];

      // Tạo log giả ở client để hiển thị (thực tế server đã lưu)
      const newLog: ChatLog = {
        id: Math.random().toString(36).substr(2, 9),
        userId,
        customerSessionId: 'anon',
        query: message,
        answer: data.text,
        timestamp: Date.now(),
        tokens: 0,
        isSolved: true
      };
      db.chatLogs.push(newLog);
      localStorage.setItem('omnichat_db_v1', JSON.stringify(db));

      return data.text;
    } catch (e) {
      return "Lỗi kết nối AI Server.";
    }
  }
};

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import CustomerManagement from './components/CustomerManagement';
import ChatHistory from './components/ChatHistory';
import Login from './components/Login';
import { View, Document, WidgetSettings, User } from './types';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  useEffect(() => {
    // Kiểm tra session cũ từ localStorage (nếu có) nhưng nên xác thực lại với server trong thực tế
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role'); // Lưu thêm role để check nhanh

    if (savedUserId) {
      // Mock login state recovery - Trong thực tế cần API /me
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      // Load fresh data
      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') { // Handle hardcoded master fallback
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@omnichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }
  }, []);

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) return <Login onLogin={handleLoginSuccess} />;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50 relative font-sans text-gray-900 antialiased">
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      {/* 
         Thay đổi ở đây: Loại bỏ max-w trên container chính để thanh cuộn nằm sát mép phải.
         Dùng w-full cho container cuộn, và đặt max-w bên trong nội dung.
      */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 z-30 shrink-0 shadow-sm">
          <div className="flex items-center space-x-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-gray-400 hover:bg-gray-100 rounded-xl transition-colors">
              <i className="fas fa-bars text-lg"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">
                {currentView.replace(/_/g, ' ')}
              </h1>
              <p className="text-xs font-bold text-gray-800 hidden sm:block">
                {currentUser?.role === 'master' ? 'Hệ thống Quản trị Master' : 'Hệ thống Quản trị Doanh nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <div className="flex items-center bg-gray-50 text-gray-700 px-3 py-1.5 rounded-xl border border-gray-100">
              <i className={`fas ${currentUser?.role === 'master' ? 'fa-crown text-yellow-500' : 'fa-user text-blue-400'} mr-2`}></i>
              <span className="text-xs font-bold truncate max-w-[150px]">{currentUser?.email}</span>
            </div>
          </div>
        </header>

        {/* Thanh cuộn sẽ nằm trên div này (w-full) */}
        <div className="flex-1 overflow-y-auto w-full scroll-smooth bg-gray-50">
          {/* Nội dung được căn giữa nhưng thanh cuộn vẫn ở mép phải */}
          <div className="p-4 lg:p-8 max-w-7xl mx-auto w-full">
            {currentView === View.DASHBOARD && (
              <Dashboard 
                user={currentUser!} 
                initialSelectedUser={selectedCustomerIdForStats} 
              />
            )}
            {currentView === View.KNOWLEDGE_BASE && (
              <KnowledgeBase 
                userId={currentUser!.id}
                documents={documents} 
                onAddDocument={addDocument} 
                onDeleteDocument={deleteDocument} 
              />
            )}
            {currentView === View.CHAT_HISTORY && (
              <ChatHistory user={currentUser!} />
            )}
            {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
            {currentView === View.INTEGRATION && <Integration userId={currentUser!.id} />}
            {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
            {currentView === View.CUSTOMER_MANAGEMENT && currentUser?.role === 'master' && (
              <CustomerManagement onViewStats={handleViewCustomerStats} />
            )}
          </div>
        </div>

        {currentUser?.role !== 'master' && (
          <div className="fixed bottom-4 right-4 z-50">
            <ChatWidget settings={settings} userId={currentUser!.id} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

// --- HELPER: LOCAL STORAGE FALLBACK ---
const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  if (!data) {
    const defaultDB = { 
      users: [
        {
          id: 'admin',
          email: 'admin@omnichat.io',
          password: '123456',
          role: 'master' as UserRole,
          createdAt: Date.now(),
          botSettings: { 
            botName: 'OmniBot', 
            primaryColor: '#2563eb', 
            welcomeMessage: 'Xin chào! Hệ thống đang chạy chế độ Offline.', 
            position: 'right', 
            avatarUrl: '' 
          }
        }
      ], 
      documents: [],
      chatLogs: []
    };
    localStorage.setItem(DB_KEY, JSON.stringify(defaultDB));
    return defaultDB;
  }
  return JSON.parse(data);
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage");
      const db = getLocalDB();
      if (db.users.find((u: any) => u.email === email)) {
        return { success: false, message: 'Email đã tồn tại (Offline)' };
      }
      const newUser: User = {
        id: Math.random().toString(36).substring(2, 11),
        email,
        password,
        role: 'user',
        createdAt: Date.now(),
        botSettings: {
          botName: 'Trợ lý AI',
          primaryColor: '#2563eb',
          welcomeMessage: 'Xin chào!',
          position: 'right',
          avatarUrl: ''
        }
      };
      db.users.push(newUser);
      saveLocalDB(db);
      return { success: true, message: 'Đăng ký thành công (Offline Mode)', user: newUser };
    }
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      // Nếu server trả về lỗi kết nối hoặc không phải JSON
      if (!res.ok) throw new Error("Server response not ok");
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();
      const user = db.users.find((u: any) => u.email === email && u.password === password);
      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      const users: User[] = await res.json();
      return users.filter(u => u.id !== 'admin'); 
    } catch (e) {
      const db = getLocalDB();
      return db.users.filter((u: any) => u.id !== 'admin');
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      db.documents = db.documents.filter((d: any) => d.userId !== targetUserId);
      db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
