    // Lưu ý: Trong Production thực tế, nên gọi qua Server để ẩn API Key.
    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      const reply = response.text || "Tôi không thể trả lời.";

      // 3. Lưu Log vào LocalStorage (để hiển thị thống kê ngay)
      const db = getLocalDB();
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        query: message,
        answer: reply,
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveLocalDB(db);

      return reply;
    } catch (e) {
      console.error(e);
      return "Lỗi AI hoặc mất kết nối mạng.";
    }
  }
};

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

// Cấu hình tài khoản Master mặc định
const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@omnichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
  botSettings: { 
    botName: 'OmniBot', 
    primaryColor: '#2563eb', 
    welcomeMessage: 'Xin chào! Hệ thống quản trị Master (Offline Mode).', 
    position: 'right', 
    avatarUrl: '' 
  }
};

// --- HELPER: LOCAL STORAGE FALLBACK ---
const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  let db;

  if (!data) {
    db = { 
      users: [MASTER_USER], 
      documents: [],
      chatLogs: []
    };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    // Tự sửa lỗi: Nếu DB tồn tại nhưng mất tài khoản admin, tự động thêm lại
    if (!db.users.find((u: any) => u.id === 'admin')) {
      db.users.unshift(MASTER_USER);
      localStorage.setItem(DB_KEY, JSON.stringify(db));
    }
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage");
      const db = getLocalDB();
      if (db.users.find((u: any) => u.email === email)) {
        return { success: false, message: 'Email đã tồn tại (Offline)' };
      }
      const newUser: User = {
        id: Math.random().toString(36).substring(2, 11),
        email,
        password,
        role: 'user',
        createdAt: Date.now(),
        botSettings: {
          botName: 'Trợ lý AI',
          primaryColor: '#2563eb',
          welcomeMessage: 'Xin chào!',
          position: 'right',
          avatarUrl: ''
        }
      };
      db.users.push(newUser);
      saveLocalDB(db);
      return { success: true, message: 'Đăng ký thành công (Offline Mode)', user: newUser };
    }
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      // Nếu server trả về lỗi kết nối hoặc không phải JSON
      if (!res.ok) throw new Error("Server response not ok");
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();

      let user = db.users.find((u: any) => u.email === email && u.password === password);

      // FALLBACK CỨU HỘ: Nếu không tìm thấy user nhưng thông tin nhập vào khớp với Master mặc định
      // (Trường hợp LocalStorage bị lỗi hoặc bị xóa mất user admin)
      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) {
        user = MASTER_USER;
        // Khôi phục lại vào DB để lần sau dùng được
        if (!db.users.find((u: any) => u.id === 'admin')) {
           db.users.unshift(MASTER_USER);
           saveLocalDB(db);
        }
      }

      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      const users: User[] = await res.json();
      return users.filter(u => u.id !== 'admin'); 
    } catch (e) {
      const db = getLocalDB();
      return db.users.filter((u: any) => u.id !== 'admin');
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      db.documents = db.documents.filter((d: any) => d.userId !== targetUserId);
      db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      // Ưu tiên Server
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      const doc = await res.json();
      if (type === 'file') doc.type = 'file'; 
      return doc;
    } catch (e) {
      // Fallback LocalStorage
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];
    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }
    return logs.sort((a, b) => b.timestamp - a.timestamp);
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    let context = "";
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if(res.ok) {
        const docs: Document[] = await res.json();
        context = docs.map(d => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      } else { throw new Error("API Docs Error"); }
    } catch (e) {
       const db = getLocalDB();
       context = db.documents.filter((d: any) => d.userId === userId)
         .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
    }

    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      const reply = response.text || "Tôi không thể trả lời.";

      const db = getLocalDB();
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        query: message,
        answer: reply,
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveLocalDB(db);

      return reply;
    } catch (e) {
      console.error(e);
      return "Lỗi AI hoặc mất kết nối mạng.";
    }
  }
};

import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Hãy đăng nhập.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Có lỗi xảy ra trong quá trình xử lý.');
    } finally {
      setIsLoading(false);
    }
  };

  const fillAdminCreds = () => {
    setEmail('admin@omnichat.io');
    setPassword('123456');
    setError('');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-50 p-4 font-sans">
      <div className="max-w-md w-full space-y-8 bg-white p-8 lg:p-10 rounded-3xl shadow-xl border border-gray-100 animate-in fade-in zoom-in duration-300">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-4 shadow-lg shadow-blue-100">
            <i className="fa-solid fa-rocket"></i>
          </div>
          <h2 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tight">
            {isRegister ? 'Tạo tài khoản SaaS' : 'Đăng nhập OmniChat'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">Nền tảng AI Chatbot cho doanh nghiệp.</p>
        </div>

        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-4 rounded-xl text-xs font-bold border ${error.includes('thành công') ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'}`}>
              <i className={`fa-solid ${error.includes('thành công') ? 'fa-circle-check' : 'fa-circle-exclamation'} mr-2`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Email doanh nghiệp</label>
              <input 
                type="email" 
                required 
                value={email} 
                onChange={(e) => setEmail(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="name@company.com" 
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Mật khẩu</label>
              <input 
                type="password" 
                required 
                value={password} 
                onChange={(e) => setPassword(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="••••••••" 
              />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full flex justify-center py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-blue-200 active:scale-[0.98] items-center"
          >
            {isLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào trang quản trị')}
          </button>
        </form>

        {!isRegister && (
          <div className="text-center">
            <button 
              type="button"
              onClick={fillAdminCreds}
              className="text-[11px] font-bold text-slate-400 hover:text-blue-600 transition-colors bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100 hover:border-blue-200"
            >
              <i className="fa-solid fa-key mr-1"></i>
              Dùng thử Master: admin@omnichat.io / 123456
            </button>
          </div>
        )}

        <div className="text-center pt-2">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }} 
            className="text-xs font-bold text-blue-600 hover:text-blue-800 transition-colors"
          >
            {isRegister ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký dùng thử'}
          </button>
        </div>

        <div className="pt-6 border-t border-gray-100 mt-6 flex justify-center space-x-4">
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-shield-halved mr-1.5"></i> Data Encryption
           </div>
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-cloud mr-1.5"></i> Cloud SaaS
           </div>
        </div>
      </div>
    </div>
  );
};

