    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    if (!db.users.find((u: any) => u.id === 'admin')) {
      db.users.unshift(MASTER_USER);
      localStorage.setItem(DB_KEY, JSON.stringify(db));
    }
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    // 1. Tạo user object
    const newUser: User = {
      id: Math.random().toString(36).substring(2, 11),
      email,
      password,
      role: 'user',
      createdAt: Date.now(),
      botSettings: {
        botName: 'Trợ lý AI',
        primaryColor: '#2563eb',
        welcomeMessage: 'Xin chào!',
        position: 'right',
        avatarUrl: ''
      }
    };

    // 2. Luôn lưu vào LocalStorage (Shadow Save) để đảm bảo Admin nhìn thấy ngay
    const db = getLocalDB();
    if (db.users.find((u: any) => u.email === email)) {
      // Nếu local đã có thì thôi, nhưng vẫn tiếp tục thử gọi server
    } else {
      db.users.push(newUser);
      saveLocalDB(db);
    }

    // 3. Gọi Server (nếu online)
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (res.ok) {
         const serverRes = await res.json();
         // Ưu tiên dùng ID từ server nếu có
         return serverRes;
      }
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");
    }

    // Trả về kết quả thành công dựa trên LocalStorage
    return { success: true, message: 'Đăng ký thành công (Offline/Hybrid)', user: newUser };
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (!res.ok) throw new Error("Server response not ok");
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();

      let user = db.users.find((u: any) => u.email === email && u.password === password);

      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) {
        user = MASTER_USER;
        if (!db.users.find((u: any) => u.id === 'admin')) {
           db.users.unshift(MASTER_USER);
           saveLocalDB(db);
        }
      }

      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    const localDB = getLocalDB();
    const localUsers: User[] = localDB.users;

    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      const serverUsers: User[] = await res.json();

      // Merge: Lấy tất cả user từ Local + Server, loại bỏ trùng lặp email
      const map = new Map();

      // Ưu tiên local users trước để đảm bảo những user vừa tạo (chưa sync server) được hiện
      [...localUsers, ...serverUsers].forEach(u => {
        if (!map.has(u.email)) {
          map.set(u.email, u);
        }
      });

      const combinedUsers = Array.from(map.values());
      return combinedUsers.filter((u: any) => u.id !== 'admin'); 
    } catch (e) {
      return localUsers.filter(u => u.id !== 'admin');
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      db.documents = db.documents.filter((d: any) => d.userId !== targetUserId);
      db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      const doc = await res.json();
      if (type === 'file') doc.type = 'file'; 
      return doc;
    } catch (e) {
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];
    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }
    return logs.sort((a, b) => b.timestamp - a.timestamp);
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    let context = "";
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if(res.ok) {
        const docs: Document[] = await res.json();
        context = docs.map(d => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      } else { throw new Error("API Docs Error"); }
    } catch (e) {
       const db = getLocalDB();
       context = db.documents.filter((d: any) => d.userId === userId)
         .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
    }

    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      const reply = response.text || "Tôi không thể trả lời.";

      const db = getLocalDB();
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        query: message,
        answer: reply,
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveLocalDB(db);

      return reply;
    } catch (e) {
      console.error(e);
      return "Lỗi AI hoặc mất kết nối mạng.";
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Dropdown state
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-7 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-5 bg-white p-7 border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">
            <i className="fa-solid fa-chart-pie text-blue-600 mr-2"></i>
            Thống kê hoạt động AI
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem khách hàng: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Dữ liệu tương tác thời gian thực từ widget.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-64" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-4 py-3 bg-slate-50 border border-slate-200 text-sm font-bold hover:bg-white hover:border-blue-400 transition-all text-slate-700"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 shadow-xl z-50 max-h-60 overflow-y-auto">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 ${selectedUser === 'all' ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 border-t border-slate-50 ${selectedUser === c.id ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-slate-100 p-1">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-2 text-[11px] font-extrabold uppercase tracking-widest transition-all ${
                  period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-message', color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Tỷ lệ chính xác', value: `${successRate}%`, icon: 'fa-solid fa-bolt-lightning', color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'Cần hỗ trợ lại', value: totalQueries - totalSolved, icon: 'fa-solid fa-circle-exclamation', color: 'text-rose-600', bg: 'bg-rose-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-7 shadow-sm border border-slate-200 flex items-center space-x-5 hover:shadow-md transition-all group">
            <div className={`w-14 h-14 ${stat.bg} ${stat.color} flex items-center justify-center shrink-0 transition-transform group-hover:scale-110`}>
              <i className={`${stat.icon} text-2xl`}></i>
            </div>
            <div>
              <p className="text-[11px] font-extrabold text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-900 tracking-tight">{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 shadow-sm border border-slate-200">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-12">
          <h3 className="text-lg font-extrabold text-slate-900 tracking-tight">Biểu đồ tăng trưởng tương tác</h3>
          <div className="flex items-center space-x-6">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-blue-600 rounded-none"></span>
              <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter">Tổng truy vấn</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-emerald-500 rounded-none"></span>
              <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter">Đã xử lý</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-spinner animate-spin text-blue-600 text-4xl"></i>
              <p className="mt-4 text-sm font-bold text-slate-400">Đang tổng hợp dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.15}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} 
                  dy={15} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} 
                />
                <Tooltip 
                  cursor={{stroke: '#e2e8f0', strokeWidth: 2}}
                  contentStyle={{ 
                    borderRadius: '0px', 
                    border: 'none', 
                    boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', 
                    padding: '15px',
                    fontWeight: 700,
                    fontSize: '12px'
                  }}
                />
                <Area type="monotone" dataKey="queries" stroke="#2563eb" fillOpacity={1} fill="url(#colorQueries)" strokeWidth={4} />
                <Area type="monotone" dataKey="solved" stroke="#10b981" fill="transparent" strokeWidth={3} strokeDasharray="6 6" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <i className="fa-solid fa-chart-line text-6xl mb-6 opacity-20"></i>
               <p className="text-sm font-bold">Chưa có dữ liệu nào được ghi nhận</p>
               <p className="text-xs font-medium mt-1">Các lượt chat của khách hàng sẽ hiển thị tại đây.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

