                          <i className="fa-solid fa-user"></i>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* AI Response */}
                  <div className="flex justify-start">
                    <div className="max-w-[90%] lg:max-w-[80%] space-y-1.5">
                      <div className="flex items-start gap-3">
