import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Hãy đăng nhập.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Có lỗi xảy ra trong quá trình xử lý.');
    } finally {
      setIsLoading(false);
    }
  };

  const fillAdminCreds = () => {
    setEmail('admin@omnichat.io');
    setPassword('123456');
    setError('');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-50 p-4 font-sans">
      <div className="max-w-md w-full space-y-8 bg-white p-8 lg:p-10 shadow-xl border border-gray-100 animate-in fade-in zoom-in duration-300">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-600 flex items-center justify-center text-white text-3xl mb-4 shadow-lg shadow-blue-100">
            <i className="fa-solid fa-rocket"></i>
          </div>
          <h2 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tight">
            {isRegister ? 'Tạo tài khoản SaaS' : 'Đăng nhập OmniChat'}
          </h2>
          <p className="mt-2 text-sm text-gray-500 font-medium">Nền tảng AI Chatbot cho doanh nghiệp.</p>
        </div>

        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-4 text-xs font-bold border ${error.includes('thành công') ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'}`}>
              <i className={`fa-solid ${error.includes('thành công') ? 'fa-circle-check' : 'fa-circle-exclamation'} mr-2`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Email doanh nghiệp</label>
              <input 
                type="email" 
                required 
                value={email} 
                onChange={(e) => setEmail(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="name@company.com" 
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1 ml-1 tracking-wider">Mật khẩu</label>
              <input 
                type="password" 
                required 
                value={password} 
                onChange={(e) => setPassword(e.target.value)} 
                className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none text-sm font-medium" 
                placeholder="••••••••" 
              />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full flex justify-center py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold transition-all disabled:opacity-50 shadow-lg shadow-blue-200 active:scale-[0.98] items-center"
          >
            {isLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào trang quản trị')}
          </button>
        </form>

        {!isRegister && (
          <div className="text-center">
            <button 
              type="button"
              onClick={fillAdminCreds}
              className="text-[11px] font-bold text-slate-400 hover:text-blue-600 transition-colors bg-slate-50 px-3 py-1.5 border border-slate-100 hover:border-blue-200"
            >
              <i className="fa-solid fa-key mr-1"></i>
              Dùng thử Master: admin@omnichat.io / 123456
            </button>
          </div>
        )}

        <div className="text-center pt-2">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }} 
            className="text-xs font-bold text-blue-600 hover:text-blue-800 transition-colors"
          >
            {isRegister ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký dùng thử'}
          </button>
        </div>

        <div className="pt-6 border-t border-gray-100 mt-6 flex justify-center space-x-4">
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-shield-halved mr-1.5"></i> Data Encryption
           </div>
           <div className="text-[10px] text-gray-400 flex items-center font-bold">
             <i className="fa-solid fa-cloud mr-1.5"></i> Cloud SaaS
           </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { View, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  currentView: View;
  onViewChange: (view: View) => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  user: User;
}

const Sidebar: React.FC<Props> = ({ currentView, onViewChange, onLogout, isOpen, onClose, user }) => {
  const isMaster = user.role === 'master';
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu xác nhận không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu mới phải có ít nhất 6 ký tự' });
      return;
    }

    try {
      const result = await apiService.changePassword(user.id, passwordForm.old, passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Có lỗi xảy ra' });
    }
  };

  const menuItems = [
    { id: View.DASHBOARD, label: isMaster ? 'Tổng quan hệ thống' : 'Bảng điều khiển', icon: 'fa-solid fa-chart-line' },
    ...(isMaster ? [
      { id: View.CUSTOMER_MANAGEMENT, label: 'Quản lý khách hàng', icon: 'fa-solid fa-users-gear' },
      { id: View.CHAT_HISTORY, label: 'Lịch sử toàn hệ thống', icon: 'fa-solid fa-clock-rotate-left' },
    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-clock-rotate-left' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức AI', icon: 'fa-solid fa-brain' },
      { id: View.WIDGET_CONFIG, label: 'Tùy chỉnh Widget', icon: 'fa-solid fa-palette' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
    ]),
    { id: View.DEPLOYMENT_GUIDE, label: 'Hướng dẫn sử dụng', icon: 'fa-solid fa-circle-info' },
  ];

  return (
    <>
    <div className={`
      fixed inset-y-0 left-0 z-50 w-72 bg-white border-r border-slate-200 flex flex-col py-8 transition-transform duration-300 lg:relative lg:translate-x-0
      ${isOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
    `}>
      <div className="px-8 mb-10 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className={`w-10 h-10 ${isMaster ? 'bg-slate-900' : 'bg-blue-600'} flex items-center justify-center text-white shadow-lg shadow-blue-200`}>
            <i className={`fa-solid ${isMaster ? 'fa-crown' : 'fa-comment-dots'} text-lg`}></i>
          </div>
          <span className="font-black text-2xl tracking-tighter text-slate-900">OmniChat</span>
        </div>
        <button onClick={onClose} className="lg:hidden p-2 text-slate-400 hover:text-slate-600">
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
      </div>

      <nav className="flex-1 px-4 space-y-1.5 overflow-y-auto">
        {menuItems.map(item => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={`w-full flex items-center space-x-3 px-5 py-3.5 transition-all duration-200 group ${
              currentView === item.id 
              ? (isMaster ? 'bg-slate-900 text-white font-bold' : 'bg-blue-600 text-white font-bold shadow-md shadow-blue-100')
              : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
            }`}
          >
            <i className={`${item.icon} w-5 text-center ${currentView === item.id ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'}`}></i>
            <span className="text-sm font-semibold tracking-tight">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="px-4 mt-auto space-y-3">
        {/* Profile Section */}
        <div className="bg-slate-50 p-4 border border-slate-100 group relative">
           <div className="flex items-center space-x-3 mb-3">
             <div className={`w-10 h-10 flex items-center justify-center text-white font-bold shrink-0 shadow-sm ${isMaster ? 'bg-slate-800' : 'bg-blue-500'}`}>
               {user.email.substring(0, 1).toUpperCase()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-bold text-slate-900 truncate">{isMaster ? 'Admin Master' : 'Tài khoản User'}</p>
               <p className="text-[10px] text-slate-500 truncate font-medium">{user.email}</p>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-2">
             <button 
                onClick={() => setShowPasswordModal(true)}
                className="col-span-1 text-[10px] font-bold text-slate-500 hover:text-blue-600 py-2 bg-white border border-slate-200 hover:border-blue-200 transition-all flex items-center justify-center"
              >
                <i className="fa-solid fa-key mr-1.5"></i> Đổi MK
             </button>
             <button 
               onClick={onLogout}
               className="col-span-1 text-[10px] font-bold text-slate-500 hover:text-red-600 py-2 bg-white border border-slate-200 hover:border-red-200 transition-all flex items-center justify-center"
             >
               <i className="fa-solid fa-arrow-right-from-bracket mr-1.5"></i> Thoát
             </button>
           </div>
        </div>
      </div>
    </div>

    {/* Change Password Modal */}
    {showPasswordModal && (
      <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
        <div className="bg-white shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center">
             <h3 className="font-bold text-lg text-slate-800">Đổi mật khẩu</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-8 h-8 bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-slate-200">
               <i className="fa-solid fa-xmark"></i>
             </button>
          </div>
          <form onSubmit={handleChangePassword} className="p-6 space-y-4">
             {passwordMsg.text && (
               <div className={`p-3 text-xs font-bold border ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                 <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check' : 'fa-circle-exclamation'} mr-2`}></i>
                 {passwordMsg.text}
               </div>
             )}

             <div>
               <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1">Mật khẩu hiện tại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-blue-500"
                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-blue-500"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1">Xác nhận mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-blue-500"
                 value={passwordForm.confirm}
                 onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
               />
             </div>

             <button type="submit" className="w-full py-3.5 bg-blue-600 text-white font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all active:scale-95">
               Cập nhật mật khẩu
             </button>
          </form>
        </div>
      </div>
    )}
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  onViewStats: (userId: string) => void;
}

const CustomerManagement: React.FC<Props> = ({ onViewStats }) => {
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    setIsLoading(true);
    try {
      const data = await apiService.getAllUsers();
      // Loại bỏ master
      const filtered = data.filter(u => u.role !== 'master');
      setCustomers(filtered);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;

    try {
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã reset mật khẩu cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;

    try {
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa tài khoản ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(); // Reload list
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const filteredCustomers = customers.filter(c => 
    c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.botSettings.botName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Toast Notification */}
      {actionMsg.text && (
        <div className={`fixed top-5 right-5 z-[100] px-6 py-4 shadow-2xl border flex items-center animate-in slide-in-from-right duration-300 ${actionMsg.type === 'success' ? 'bg-white border-emerald-100 text-emerald-600' : 'bg-white border-rose-100 text-rose-600'}`}>
          <i className={`fa-solid ${actionMsg.type === 'success' ? 'fa-circle-check' : 'fa-circle-exclamation'} text-xl mr-3`}></i>
          <span className="font-bold text-sm">{actionMsg.text}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-7 border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight flex items-center">
                <i className="fa-solid fa-users-gear text-blue-600 mr-3"></i>
                Quản lý khách hàng
              </h2>
              <p className="text-sm text-slate-500 font-medium mt-1">Hệ thống đang phục vụ {customers.length} doanh nghiệp.</p>
            </div>
            <button 
              onClick={loadCustomers}
              disabled={isLoading}
              className="w-9 h-9 flex items-center justify-center bg-slate-50 text-slate-500 hover:bg-blue-50 hover:text-blue-600 transition-all active:scale-90"
              title="Làm mới danh sách"
            >
              <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
            </button>
        </div>
        <div className="relative w-full md:w-80">
          <i className="fa-solid fa-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
          <input 
            type="text" 
            placeholder="Tìm theo email hoặc tên bot..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none text-sm font-medium transition-all"
          />
        </div>
      </div>

      <div className="bg-white shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Khách hàng</th>
                <th className="px-6 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest text-center">Tên AI Bot</th>
                <th className="px-6 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Ngày đăng ký</th>
                <th className="px-6 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest text-right">Hành động</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="px-8 py-24 text-center">
                    <i className="fa-solid fa-circle-notch animate-spin text-blue-600 text-3xl"></i>
                    <p className="text-sm font-bold text-slate-400 mt-4">Đang truy xuất dữ liệu...</p>
                  </td>
                </tr>
              ) : filteredCustomers.length > 0 ? (
                filteredCustomers.map(customer => (
                  <tr key={customer.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-5">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-blue-100 text-blue-600 flex items-center justify-center font-bold mr-3 text-base border border-blue-200">
                          {customer.email.charAt(0).toUpperCase()}
