  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu xác nhận không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu mới phải có ít nhất 6 ký tự' });
      return;
    }

    try {
      const result = await apiService.changePassword(user.id, passwordForm.old, passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Có lỗi xảy ra' });
    }
  };

  const menuItems = [
    { id: View.DASHBOARD, label: isMaster ? 'Tổng quan' : 'Bảng điều khiển', icon: 'fa-solid fa-chart-pie' },
    ...(isMaster ? [
      { id: View.CUSTOMER_MANAGEMENT, label: 'Khách hàng', icon: 'fa-solid fa-users-gear' },
      { id: View.CHAT_HISTORY, label: 'Lịch sử hệ thống', icon: 'fa-solid fa-clock-rotate-left' },
    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-comments' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức', icon: 'fa-solid fa-book-open' },
      { id: View.WIDGET_CONFIG, label: 'Cấu hình Widget', icon: 'fa-solid fa-paint-roller' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
    ]),
    { id: View.DEPLOYMENT_GUIDE, label: 'Hướng dẫn', icon: 'fa-solid fa-circle-question' },
  ];

  return (
    <>
    <div className={`
      fixed inset-y-0 left-0 z-50 w-72 bg-white/80 backdrop-blur-md border-r border-slate-200/60 flex flex-col py-6 transition-transform duration-300 lg:relative lg:translate-x-0
      ${isOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
    `}>
      <div className="px-6 mb-8 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 ${isMaster ? 'bg-slate-900' : 'bg-gradient-to-br from-blue-600 to-indigo-600'} rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20`}>
            <i className={`fa-solid ${isMaster ? 'fa-crown' : 'fa-robot'}`}></i>
          </div>
          <span className="font-extrabold text-xl tracking-tight text-slate-800">OmniChat</span>
        </div>
        <button onClick={onClose} className="lg:hidden w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-slate-200">
          <i className="fa-solid fa-xmark"></i>
        </button>
      </div>

      <nav className="flex-1 px-4 space-y-1.5 overflow-y-auto">
        <div className="text-[11px] font-bold text-slate-400 uppercase tracking-wider px-4 mb-2">Menu chính</div>
        {menuItems.map(item => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={`w-full flex items-center gap-3.5 px-4 py-3.5 rounded-xl transition-all duration-200 group relative overflow-hidden ${
              currentView === item.id 
              ? (isMaster ? 'bg-slate-900 text-white shadow-md shadow-slate-900/20' : 'bg-blue-50 text-blue-700 font-bold')
              : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900 font-medium'
            }`}
          >
            {currentView === item.id && !isMaster && <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-blue-600 rounded-r-full"></div>}
            <i className={`${item.icon} w-5 text-center text-lg ${currentView === item.id ? (isMaster ? 'text-white' : 'text-blue-600') : 'text-slate-400 group-hover:text-slate-600 transition-colors'}`}></i>
            <span className="text-sm">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="px-4 mt-auto">
        {/* Profile Card */}
        <div className="bg-white border border-slate-100 rounded-2xl p-4 shadow-sm relative overflow-hidden group">
           <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-purple-500"></div>
           <div className="flex items-center gap-3 mb-4">
             <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shrink-0 shadow-md ${isMaster ? 'bg-slate-800' : 'bg-gradient-to-br from-blue-500 to-indigo-500'}`}>
               {user.email.substring(0, 1).toUpperCase()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-bold text-slate-800 truncate">{isMaster ? 'Master Admin' : 'Doanh nghiệp'}</p>
               <p className="text-xs text-slate-500 truncate font-medium">{user.email}</p>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-2">
             <button 
                onClick={() => setShowPasswordModal(true)}
                className="col-span-1 text-xs font-bold text-slate-600 hover:text-blue-600 py-2 bg-slate-50 hover:bg-blue-50 rounded-lg transition-all"
              >
                Đổi mật khẩu
             </button>
             <button 
               onClick={onLogout}
               className="col-span-1 text-xs font-bold text-rose-600 hover:text-rose-700 py-2 bg-rose-50 hover:bg-rose-100 rounded-lg transition-all"
             >
               Đăng xuất
             </button>
           </div>
        </div>
      </div>
    </div>

    {/* Change Password Modal */}
    {showPasswordModal && (
      <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
             <h3 className="font-bold text-lg text-slate-800">Đổi mật khẩu bảo mật</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-100 transition-colors">
               <i className="fa-solid fa-xmark"></i>
             </button>
          </div>
          <form onSubmit={handleChangePassword} className="p-6 space-y-5">
             {passwordMsg.text && (
               <div className={`p-4 rounded-xl text-sm font-bold flex items-center ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>
                 <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-2 text-lg`}></i>
                 {passwordMsg.text}
               </div>
             )}

             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu hiện tại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Xác nhận mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                 value={passwordForm.confirm}
                 onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
               />
             </div>

             <button type="submit" className="w-full py-3.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-200 transition-all active:scale-[0.98]">
               Cập nhật mật khẩu
             </button>
          </form>
        </div>
      </div>
    )}
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-6 rounded-3xl border border-slate-100 shadow-xl shadow-slate-200/50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight mb-1">
            Hiệu suất hoạt động AI
          </h2>
          <p className="text-sm text-slate-500 font-medium">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Theo dõi tương tác khách hàng thời gian thực.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto items-center">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-64 z-20" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm font-bold hover:border-blue-400 transition-all text-slate-700 shadow-sm"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-slate-400 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl overflow-hidden max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 transition-colors ${selectedUser === 'all' ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 border-t border-slate-50 transition-colors ${selectedUser === c.id ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-slate-100 p-1 rounded-xl">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${
                  period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-comments', from: 'from-blue-500', to: 'to-blue-600', shadow: 'shadow-blue-200' },
          { label: 'Tỷ lệ giải quyết', value: `${successRate}%`, icon: 'fa-solid fa-wand-magic-sparkles', from: 'from-emerald-500', to: 'to-emerald-600', shadow: 'shadow-emerald-200' },
          { label: 'Cần hỗ trợ', value: totalQueries - totalSolved, icon: 'fa-solid fa-headset', from: 'from-rose-500', to: 'to-rose-600', shadow: 'shadow-rose-200' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-3xl shadow-lg shadow-slate-200/50 border border-slate-100 flex items-center space-x-5 hover:-translate-y-1 transition-transform duration-300">
            <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${stat.from} ${stat.to} flex items-center justify-center shrink-0 shadow-lg ${stat.shadow} text-white`}>
              <i className={`${stat.icon} text-2xl`}></i>
            </div>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-800">{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-3xl shadow-xl shadow-slate-200/40 border border-slate-100">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
          <div>
            <h3 className="text-lg font-bold text-slate-800">Biểu đồ tăng trưởng</h3>
            <p className="text-xs text-slate-400 font-medium">Số lượng câu hỏi theo thời gian</p>
          </div>
          <div className="flex items-center space-x-6 bg-slate-50 px-4 py-2 rounded-xl">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-blue-500 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Tổng truy vấn</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-emerald-500 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Đã giải quyết</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-circle-notch animate-spin text-blue-500 text-3xl mb-3"></i>
              <p className="text-sm font-bold text-slate-400">Đang tải dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorSolved" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} 
                  dy={10} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} 
                />
                <Tooltip 
                  cursor={{stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4'}}
                  contentStyle={{ 
                    borderRadius: '16px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', 
                    padding: '12px 16px',
                    fontWeight: 600,
                    fontSize: '12px',
                    backgroundColor: 'rgba(255, 255, 255, 0.95)'
                  }}
                />
                <Area type="monotone" dataKey="queries" stroke="#3b82f6" fillOpacity={1} fill="url(#colorQueries)" strokeWidth={3} activeDot={{r: 6}} />
                <Area type="monotone" dataKey="solved" stroke="#10b981" fillOpacity={1} fill="url(#colorSolved)" strokeWidth={3} />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                 <i className="fa-solid fa-chart-line text-3xl opacity-30"></i>
               </div>
               <p className="text-sm font-bold">Chưa có dữ liệu nào</p>
               <p className="text-xs mt-1">Hệ thống sẽ hiển thị biểu đồ khi có tương tác.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  onViewStats: (userId: string) => void;
}

const CustomerManagement: React.FC<Props> = ({ onViewStats }) => {
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    setIsLoading(true);
    try {
      const data = await apiService.getAllUsers();
      const filtered = data.filter(u => u.role !== 'master');
      setCustomers(filtered);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;
    try {
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã reset mật khẩu cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;
    try {
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa tài khoản ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(); 
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const filteredCustomers = customers.filter(c => 
    c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.botSettings.botName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Toast Notification */}
      {actionMsg.text && (
        <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-2xl shadow-2xl border flex items-center animate-in slide-in-from-right duration-300 ${actionMsg.type === 'success' ? 'bg-white border-emerald-100 text-emerald-600' : 'bg-white border-rose-100 text-rose-600'}`}>
          <i className={`fa-solid ${actionMsg.type === 'success' ? 'fa-circle-check' : 'fa-circle-exclamation'} text-xl mr-3`}></i>
          <span className="font-bold text-sm">{actionMsg.text}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-3xl border border-slate-100 shadow-lg shadow-slate-200/50">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800 flex items-center">
                <span className="w-8 h-8 rounded-lg bg-blue-100 text-blue-600 flex items-center justify-center mr-3 text-sm">
                  <i className="fa-solid fa-users"></i>
                </span>
                Quản lý khách hàng
              </h2>
            </div>
            <button 
              onClick={loadCustomers}
              disabled={isLoading}
