                         <span className="text-xs font-bold text-slate-600">{customer.botSettings.botName}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-sm font-medium text-slate-600 flex items-center">
                        <i className="fa-regular fa-calendar mr-2 text-slate-400"></i>
                        {new Date(customer.createdAt).toLocaleDateString('vi-VN')}
                      </p>
