import React, { useState, useEffect, useRef } from 'react';
import { apiService } from '../services/apiService';
import { ChatLog, User } from '../types';

interface Props {
  user: User;
}

const ChatHistory: React.FC<Props> = ({ user }) => {
  const isMaster = user.role === 'master';
  const [logs, setLogs] = useState<ChatLog[]>([]);
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUserFilter, setSelectedUserFilter] = useState<string>('all');
  const [selectedLog, setSelectedLog] = useState<ChatLog | null>(null);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    loadData();
  }, [user.id]);

  const loadData = async () => {
    setIsLoading(true);
    try {
      if (isMaster) {
        const allUsers = await apiService.getAllUsers();
        setCustomers(allUsers);
        const allLogs = await apiService.getChatLogs('all');
        setLogs(allLogs);
      } else {
        const myLogs = await apiService.getChatLogs(user.id);
        setLogs(myLogs);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredLogs = logs.filter(log => {
    if (selectedUserFilter === 'all') return true;
    return log.userId === selectedUserFilter;
  });

  const getCustomerEmail = (userId: string) => {
    return customers.find(c => c.id === userId)?.email || 'Unknown User';
  };

  const getFilterLabel = () => {
     if (selectedUserFilter === 'all') return 'Tất cả khách hàng';
     const found = customers.find(c => c.id === selectedUserFilter);
     return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-3xl border border-slate-100 shadow-lg shadow-slate-200/50">
        <div>
          <h2 className="text-xl font-black text-slate-800 flex items-center">
            <span className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-600 flex items-center justify-center mr-3 text-sm">
               <i className="fa-solid fa-clock-rotate-left"></i>
            </span>
            Lịch sử Trò chuyện
          </h2>
        </div>

        {isMaster && (
          <div className="w-full sm:w-auto relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full sm:w-64 flex items-center justify-between px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm font-bold hover:border-blue-400 transition-all text-slate-600 shadow-sm"
              >
                <span className="truncate">{getFilterLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-slate-400 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
            </button>

            {isDropdownOpen && (
                <div className="absolute top-full right-0 w-full sm:w-64 mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl z-50 max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200">
                  <div 
                    onClick={() => { setSelectedUserFilter('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 ${selectedUserFilter === 'all' ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                  >
                    Tất cả khách hàng
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUserFilter(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 border-t border-slate-50 ${selectedUserFilter === c.id ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List Column */}
        <div className={`lg:col-span-1 bg-white rounded-3xl shadow-lg shadow-slate-200/40 border border-slate-100 overflow-hidden flex flex-col h-[650px] ${selectedLog ? 'hidden lg:flex' : 'flex'}`}>
          <div className="p-4 border-b border-slate-100 bg-slate-50/50">
             <h3 className="font-bold text-slate-700 text-sm">Danh sách hội thoại ({filteredLogs.length})</h3>
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-3">
            {isLoading ? (
               <div className="flex justify-center p-10"><i className="fa-solid fa-circle-notch animate-spin text-blue-500 text-2xl"></i></div>
            ) : filteredLogs.length > 0 ? (
              filteredLogs.map(log => (
                <div 
                  key={log.id}
                  onClick={() => setSelectedLog(log)}
                  className={`p-4 rounded-2xl cursor-pointer transition-all border ${
                    selectedLog?.id === log.id 
                    ? 'bg-blue-50 border-blue-200 shadow-inner' 
                    : 'bg-white border-slate-100 hover:border-blue-200 hover:shadow-md'
                  }`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">
                      {new Date(log.timestamp).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                    </span>
                    {log.isSolved ? (
                      <span className="w-2 h-2 rounded-full bg-emerald-500" title="Đã xong"></span>
                    ) : (
                      <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse" title="Chưa rõ"></span>
                    )}
                  </div>
                  {isMaster && (
                    <div className="text-xs font-bold text-blue-600 mb-2 truncate flex items-center">
                      <i className="fa-solid fa-user-circle mr-1.5 text-blue-400"></i>
                      {getCustomerEmail(log.userId)}
                    </div>
                  )}
                  <p className={`text-sm font-medium line-clamp-2 leading-relaxed ${selectedLog?.id === log.id ? 'text-slate-800' : 'text-slate-500'}`}>
                    {log.query || <span className="italic opacity-50">Không có nội dung</span>}
                  </p>
                </div>
              ))
            ) : (
              <div className="text-center p-10 text-slate-400">
                <i className="fa-regular fa-comments text-4xl mb-4 opacity-30"></i>
                <p className="text-sm font-medium">Chưa có dữ liệu</p>
              </div>
            )}
          </div>
        </div>

        {/* Detail Column */}
        <div className={`lg:col-span-2 bg-slate-50 rounded-3xl shadow-inner border border-slate-200 overflow-hidden flex flex-col h-[650px] ${!selectedLog ? 'hidden lg:flex' : 'flex'}`}>
           {selectedLog ? (
             <>
                <div className="p-4 border-b border-slate-200 bg-white flex justify-between items-center shadow-sm z-10">
                  <div className="flex items-center gap-3">
                    <button onClick={() => setSelectedLog(null)} className="lg:hidden w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center text-slate-500">
                      <i className="fa-solid fa-arrow-left"></i>
                    </button>
                    <div>
                      <h3 className="font-bold text-slate-800 text-sm">Chi tiết phiên chat</h3>
                      <p className="text-[10px] text-slate-400 font-mono mt-0.5">
                        #{selectedLog.id}
                      </p>
                    </div>
                  </div>
                  {isMaster && (
                    <div className="hidden sm:flex text-xs font-bold bg-blue-50 text-blue-700 px-3 py-1.5 rounded-lg border border-blue-100 items-center">
                      <i className="fa-solid fa-building-user mr-2 text-blue-500"></i>
                      {getCustomerEmail(selectedLog.userId)}
                    </div>
                  )}
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                  {/* Time Separator */}
                  <div className="flex justify-center">
                    <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-3 py-1 rounded-full">
                      {new Date(selectedLog.timestamp).toLocaleString('vi-VN')}
                    </span>
                  </div>

                  {/* User Message */}
                  <div className="flex justify-end">
                    <div className="max-w-[85%] lg:max-w-[75%] space-y-1">
                      <div className="bg-gradient-to-br from-blue-600 to-indigo-600 text-white px-5 py-3 rounded-2xl rounded-tr-none shadow-md shadow-blue-500/20 text-[15px] font-medium leading-relaxed">
                        {selectedLog.query}
                      </div>
                      <div className="text-[10px] text-slate-400 font-bold text-right mr-2">Khách hàng</div>
                    </div>
                  </div>

                  {/* AI Response */}
                  <div className="flex justify-start">
                    <div className="max-w-[90%] lg:max-w-[80%] space-y-1">
                      <div className="flex items-start gap-3">
                         <div className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-indigo-600 text-sm shadow-sm shrink-0 mt-1">
                           <i className="fa-solid fa-robot"></i>
                         </div>
                         <div>
                            <div className="bg-white text-slate-800 border border-slate-100 px-5 py-3 rounded-2xl rounded-tl-none shadow-sm text-[15px] font-medium leading-relaxed whitespace-pre-wrap">
                              {selectedLog.answer}
                            </div>
                            <div className="flex items-center gap-2 mt-1.5 ml-2">
                              <span className="text-[10px] text-slate-400 font-bold">AI Assistant</span>
                              {!selectedLog.isSolved && (
                                <span className="text-[10px] text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full font-bold flex items-center border border-rose-100">
                                  <i className="fa-solid fa-circle-exclamation mr-1"></i>
                                  Chưa xử lý được
                                </span>
                              )}
                            </div>
                         </div>
                      </div>
                    </div>
                  </div>
                </div>
             </>
           ) : (
             <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-24 h-24 bg-white rounded-full border border-slate-100 shadow-sm flex items-center justify-center mb-6">
                 <i className="fa-regular fa-comments text-4xl text-blue-200"></i>
               </div>
               <p className="text-lg font-bold text-slate-700">Chưa chọn hội thoại</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

export default ChatHistory;

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
}

const ChatWidget: React.FC<Props> = ({ settings, userId }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await apiService.chat(userId, input, settings.botName);
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Hệ thống đang bận. Vui lòng thử lại sau.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`fixed bottom-6 ${settings.position === 'right' ? 'right-6' : 'left-6'} z-[9999] font-sans`}>
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className="w-16 h-16 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-all hover:scale-110 active:scale-95 duration-300 relative group" 
        style={{ backgroundColor: settings.primaryColor }}
      >
        <span className="absolute inset-0 rounded-full bg-white opacity-20 group-hover:animate-ping"></span>
        {isOpen ? <i className="fa-solid fa-xmark"></i> : <i className="fa-solid fa-comment-dots"></i>}
      </button>

      {isOpen && (
        <div className={`absolute bottom-24 ${settings.position === 'right' ? 'right-0' : 'left-0'} w-[calc(100vw-3rem)] sm:w-[380px] h-[550px] bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in slide-in-from-bottom-10 duration-300 border border-slate-100/50`}>
          {/* Header */}
          <div className="p-5 text-white relative overflow-hidden" style={{ backgroundColor: settings.primaryColor }}>
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <i className="fa-solid fa-robot text-6xl"></i>
            </div>
            <div className="flex items-center space-x-3 relative z-10">
              <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center border-2 border-white/30 backdrop-blur-sm">
                <i className="fa-solid fa-robot text-xl"></i>
              </div>
              <div>
                <h3 className="font-bold text-lg">{settings.botName}</h3>
                <div className="flex items-center text-xs opacity-90 font-medium bg-white/20 px-2 py-0.5 rounded-full w-fit mt-1">
                  <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full mr-1.5 animate-pulse"></span>
                  Trực tuyến
                </div>
              </div>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 p-5 bg-slate-50 space-y-4 overflow-y-auto">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 text-sm font-medium shadow-sm leading-relaxed ${
                  msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-2xl rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-2xl rounded-tl-none'
                }`} style={msg.role === 'user' ? { backgroundColor: settings.primaryColor } : {}}>
                  <p className="whitespace-pre-wrap">{msg.text}</p>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white px-4 py-3 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm flex space-x-1.5 items-center">
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
