                          {doc.type}
                        </span>
                      </td>
                      <td className="px-8 py-5">
                        <span className="inline-flex items-center text-[10px] font-extrabold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100">
