              </p>
              <div className="flex items-center text-xs font-bold text-blue-400 hover:text-blue-300 cursor-pointer transition-colors">
                <i className="fa-solid fa-arrow-right mr-2"></i>
                Xem tài liệu mẫu
              </div>
            </div>
            <div className="absolute -right-6 -bottom-6 w-32 h-32 bg-white/5 rounded-full blur-2xl group-hover:bg-white/10 transition-colors duration-500"></div>
          </div>
        </div>
      </div>
    </div>
  );
};

