          <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-pink-50/30">
             <h3 className="font-bold text-xl text-slate-800">Đổi mật khẩu nha</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center text-slate-400 hover:bg-pink-50 hover:text-pink-500 transition-colors">
