             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Mật khẩu hiện tại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 border-2 border-transparent focus:border-pink-300 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white transition-all text-slate-700 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 border-2 border-transparent focus:border-pink-300 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white transition-all text-slate-700 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Xác nhận lại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 border-2 border-transparent focus:border-pink-300 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white transition-all text-slate-700 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.confirm}
                 onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
               />
             </div>

             <button type="submit" className="w-full py-4 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-2xl font-bold shadow-lg shadow-pink-200 transition-all active:scale-[0.98] mt-2">
               Cập nhật ngay
             </button>
          </form>
        </div>
      </div>
    )}
    </>
  );
};

