import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Đăng nhập đi nè.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Huhu, có lỗi gì đó rồi.');
    } finally {
      setIsLoading(false);
    }
  };

  const fillAdminCreds = () => {
    setEmail('admin@omnichat.io');
    setPassword('123456');
    setError('');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#fff0f5] p-6 font-sans relative overflow-hidden">
      {/* Background Decor - Cute Blobs */}
