        <div className="text-center mb-10">
          <div className="mx-auto w-20 h-20 bg-gradient-to-br from-pink-400 to-rose-400 rounded-3xl flex items-center justify-center text-white text-3xl shadow-xl shadow-pink-300/50 mb-6 transform -rotate-6 hover:rotate-6 transition-transform cursor-pointer">
            <i className="fa-solid fa-heart"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight mb-2">
