  const [searchTerm, setSearchTerm] = useState('');

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    setIsLoading(true);
    try {
      const data = await apiService.getAllUsers();
      const filtered = data.filter(u => u.role !== 'master');
      setCustomers(filtered);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;
    try {
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã đổi pass cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;
    try {
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa bé ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(); 
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const filteredCustomers = customers.filter(c => 
    c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.botSettings.botName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Toast Notification */}
      {actionMsg.text && (
        <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-3xl shadow-xl border flex items-center animate-in slide-in-from-right duration-300 ${actionMsg.type === 'success' ? 'bg-white border-emerald-100 text-emerald-600' : 'bg-white border-rose-100 text-rose-600'}`}>
          <i className={`fa-solid ${actionMsg.type === 'success' ? 'fa-check-circle' : 'fa-heart-crack'} text-xl mr-3`}></i>
          <span className="font-bold text-sm">{actionMsg.text}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-[2rem] border border-white shadow-lg shadow-purple-50">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800 flex items-center">
                <span className="w-10 h-10 rounded-2xl bg-pink-100 text-pink-500 flex items-center justify-center mr-3 text-lg">
                  <i className="fa-solid fa-users"></i>
                </span>
                Quản lý khách hàng
              </h2>
            </div>
            <button 
              onClick={loadCustomers}
              disabled={isLoading}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 text-slate-400 hover:bg-pink-100 hover:text-pink-500 transition-all active:scale-90 border border-slate-100 shadow-sm"
              title="Làm mới danh sách"
            >
              <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
            </button>
        </div>
        <div className="relative w-full md:w-80 group">
          <i className="fa-solid fa-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-pink-500 transition-colors"></i>
          <input 
            type="text" 
            placeholder="Tìm theo email hoặc tên bot..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-5 py-3.5 bg-slate-50 border-2 border-slate-50 rounded-full focus:border-pink-300 focus:bg-white outline-none text-sm font-bold transition-all text-slate-700"
          />
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-white overflow-hidden p-2">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-slate-50">
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider pl-8">Khách hàng</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-center">Tên AI Bot</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">Ngày tham gia</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-right pr-8">Hành động</th>
              </tr>
            </thead>
            <tbody className="space-y-2">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="px-8 py-24 text-center">
                    <i className="fa-solid fa-circle-notch animate-spin text-pink-400 text-3xl"></i>
                    <p className="text-sm font-bold text-slate-400 mt-4">Đang tìm kiếm...</p>
                  </td>
                </tr>
              ) : filteredCustomers.length > 0 ? (
                filteredCustomers.map(customer => (
                  <tr key={customer.id} className="hover:bg-purple-50/50 transition-colors group rounded-2xl">
                    <td className="px-6 py-4 pl-8 rounded-l-2xl">
                      <div className="flex items-center">
                        <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-pink-200 to-purple-200 text-purple-600 flex items-center justify-center font-bold mr-4 text-lg shadow-sm border-2 border-white">
                          {customer.email.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-800">{customer.email}</p>
                          <p className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full inline-block mt-1">#{customer.id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="inline-flex items-center px-4 py-2 bg-white rounded-full border border-slate-100 shadow-sm">
                         <span className="w-2.5 h-2.5 rounded-full mr-2" style={{ backgroundColor: customer.botSettings.primaryColor }}></span>
                         <span className="text-xs font-bold text-slate-600">{customer.botSettings.botName}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-sm font-bold text-slate-500 flex items-center">
                        <i className="fa-regular fa-calendar-heart mr-2 text-pink-300"></i>
                        {new Date(customer.createdAt).toLocaleDateString('vi-VN')}
                      </p>
                    </td>
                    <td className="px-6 py-4 text-right pr-8 rounded-r-2xl">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => onViewStats(customer.id)}
                          className="w-10 h-10 flex items-center justify-center bg-blue-50 text-blue-500 rounded-full hover:bg-blue-500 hover:text-white transition-all shadow-sm hover:scale-110"
                          title="Xem báo cáo"
                        >
                          <i className="fa-solid fa-chart-line text-sm"></i>
                        </button>
                        <button 
                          onClick={() => {
                            setResetModal({ isOpen: true, userId: customer.id, email: customer.email });
                            setNewResetPassword('');
                          }}
                          className="w-10 h-10 flex items-center justify-center bg-amber-50 text-amber-500 rounded-full hover:bg-amber-500 hover:text-white transition-all shadow-sm hover:scale-110"
                          title="Reset mật khẩu"
                        >
                          <i className="fa-solid fa-key text-sm"></i>
                        </button>
                        <button 
                          onClick={() => setDeleteModal({ isOpen: true, userId: customer.id, email: customer.email })}
                          className="w-10 h-10 flex items-center justify-center bg-rose-50 text-rose-500 rounded-full hover:bg-rose-500 hover:text-white transition-all shadow-sm hover:scale-110"
                          title="Xóa tài khoản"
                        >
                          <i className="fa-solid fa-trash-can text-sm"></i>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4} className="px-8 py-32 text-center">
                    <div className="max-w-xs mx-auto">
                      <div className="w-24 h-24 bg-pink-50 rounded-full flex items-center justify-center text-pink-200 mx-auto mb-6">
                        <i className="fa-solid fa-face-sad-tear text-4xl"></i>
                      </div>
                      <h3 className="text-lg font-bold text-slate-800">Không tìm thấy ai hết</h3>
                      <p className="text-sm text-slate-500 mt-2 font-medium">Thử tìm từ khóa khác xem sao nha.</p>
                      <button onClick={loadCustomers} className="mt-4 text-pink-500 font-bold text-sm hover:underline">
                        Tải lại danh sách
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Reset Password Modal */}
      {resetModal.isOpen && (
        <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-300 border border-white">
             <div className="p-8 text-center">
               <div className="w-20 h-20 bg-amber-100 text-amber-500 rounded-3xl flex items-center justify-center mx-auto mb-5 text-3xl shadow-lg shadow-amber-200 transform rotate-12">
                 <i className="fa-solid fa-key"></i>
               </div>
               <h3 className="text-xl font-black text-slate-800">Reset mật khẩu</h3>
