                 <button onClick={handleDeleteUser} className="py-3.5 bg-rose-500 text-white rounded-2xl font-bold hover:bg-rose-600 transition-colors shadow-lg shadow-rose-200">Xóa luôn</button>
               </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

