  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  // Notification State
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  // Fake Notifications Data - Neutral/Cute version
  const notifications = [
    { id: 1, title: 'Cập nhật hệ thống', desc: 'Đã nâng cấp lên Gemini 3.5 Flash siêu tốc!', time: '2 giờ trước', icon: 'fa-bolt', color: 'text-amber-500', bg: 'bg-amber-100' },
    { id: 2, title: 'Sao lưu dữ liệu', desc: 'Dữ liệu của bạn đã được mã hóa an toàn.', time: '5 giờ trước', icon: 'fa-database', color: 'text-emerald-500', bg: 'bg-emerald-100' },
    { id: 3, title: 'Cảnh báo đăng nhập', desc: 'Phát hiện đăng nhập từ thiết bị lạ.', time: '1 ngày trước', icon: 'fa-shield-halved', color: 'text-rose-500', bg: 'bg-rose-100' },
    { id: 4, title: 'Chào mừng bạn', desc: 'Hệ thống đã sẵn sàng phục vụ.', time: '2 ngày trước', icon: 'fa-hand-sparkles', color: 'text-indigo-500', bg: 'bg-indigo-100' },
  ];

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#6366f1', // Indigo-500 default (Neutral)
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  // Map view names to Vietnamese
  const viewNames: Record<View, string> = {
    [View.DASHBOARD]: 'Tổng quan',
    [View.KNOWLEDGE_BASE]: 'Kho tri thức',
    [View.WIDGET_CONFIG]: 'Làm đẹp Widget',
    [View.ANALYTICS]: 'Phân tích',
    [View.INTEGRATION]: 'Mã nhúng',
    [View.DEPLOYMENT_GUIDE]: 'Hướng dẫn',
    [View.CUSTOMER_MANAGEMENT]: 'Khách hàng',
    [View.CHAT_HISTORY]: 'Lịch sử chat'
  };

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role');

    if (savedUserId) {
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') {
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@omnichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }

    const handleClickOutside = (event: MouseEvent) => {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);

  }, []);

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) return <Login onLogin={handleLoginSuccess} />;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50 relative font-sans text-slate-700 antialiased selection:bg-indigo-100 selection:text-indigo-900">
      {/* Decorative Blobs - Cool Tones */}
      <div className="absolute top-[-10%] right-[-5%] w-[500px] h-[500px] bg-indigo-200/20 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-10%] left-[-5%] w-[500px] h-[500px] bg-teal-200/20 rounded-full blur-[100px] pointer-events-none"></div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative z-10">
        <header className="h-24 flex items-center justify-between px-8 z-30 shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden w-12 h-12 bg-white rounded-2xl shadow-sm flex items-center justify-center text-indigo-500 hover:text-indigo-600 transition-colors">
              <i className="fas fa-bars text-xl"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-3xl font-bold text-slate-800 tracking-tight">
                {viewNames[currentView]}
              </h1>
              <p className="text-sm font-semibold text-slate-400 hidden sm:block">
                {currentUser?.role === 'master' ? '🚀 Control Center' : '✨ Dashboard Doanh Nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-5">
             <div className="hidden md:flex items-center gap-2 bg-white/60 backdrop-blur-sm px-4 py-2 rounded-full border border-white shadow-sm">
                <div className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse"></div>
                <span className="text-sm font-bold text-slate-600">Hệ thống ổn định</span>
             </div>

             {/* Notification Bell - Neutral Cute */}
             <div className="relative" ref={notifRef}>
               <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className="w-12 h-12 bg-white rounded-full shadow-md flex items-center justify-center text-slate-400 hover:text-indigo-500 hover:scale-110 transition-all relative active:scale-95 group border border-slate-50"
               >
                 <i className="fa-regular fa-bell text-xl group-hover:animate-swing"></i>
                 <span className="absolute top-3 right-3.5 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white"></span>
               </button>

               {/* Notification Dropdown */}
               {showNotifications && (
                 <div className="absolute right-0 mt-4 w-80 bg-white/95 backdrop-blur-xl rounded-[2rem] shadow-[0_20px_40px_-10px_rgba(0,0,0,0.1)] border border-white overflow-hidden animate-in fade-in zoom-in duration-200 z-50">
                    <div className="p-5 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                       <h3 className="font-bold text-base text-slate-800">Thông báo</h3>
                       <span className="text-[10px] bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full font-bold">Mới nhất</span>
                    </div>
                    <div className="max-h-80 overflow-y-auto p-2">
                       {notifications.map(notif => (
                         <div key={notif.id} className="p-3 mb-1 hover:bg-slate-50 rounded-2xl transition-colors cursor-pointer group">
                            <div className="flex gap-4">
                               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm`}>
                                  <i className={`fa-solid ${notif.icon} text-lg`}></i>
                               </div>
                               <div>
                                  <h4 className="text-sm font-bold text-slate-700 group-hover:text-indigo-600 transition-colors">{notif.title}</h4>
                                  <p className="text-xs text-slate-500 mt-1 leading-relaxed">{notif.desc}</p>
                                  <p className="text-[10px] text-slate-400 font-bold mt-1.5">{notif.time}</p>
                               </div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <div className="p-3 text-center border-t border-slate-50">
                       <button className="text-xs font-bold text-indigo-500 hover:text-indigo-700 hover:underline">Đánh dấu đã đọc</button>
                    </div>
                 </div>
               )}
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto w-full scroll-smooth p-6 lg:p-8 pt-0 no-scrollbar">
          <div className="max-w-7xl mx-auto w-full">
            {currentView === View.DASHBOARD && (
              <Dashboard 
                user={currentUser!} 
                initialSelectedUser={selectedCustomerIdForStats} 
              />
            )}
            {currentView === View.KNOWLEDGE_BASE && (
              <KnowledgeBase 
                userId={currentUser!.id}
                documents={documents} 
                onAddDocument={addDocument} 
                onDeleteDocument={deleteDocument} 
              />
            )}
            {currentView === View.CHAT_HISTORY && (
              <ChatHistory user={currentUser!} />
            )}
            {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
            {currentView === View.INTEGRATION && <Integration userId={currentUser!.id} />}
            {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
            {currentView === View.CUSTOMER_MANAGEMENT && currentUser?.role === 'master' && (
              <CustomerManagement onViewStats={handleViewCustomerStats} />
            )}
          </div>
        </div>

        {currentUser?.role !== 'master' && (
          <div className="fixed bottom-6 right-6 z-50">
            <ChatWidget settings={settings} userId={currentUser!.id} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Đăng nhập đi nè.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Huhu, có lỗi gì đó rồi.');
    } finally {
      setIsLoading(false);
    }
  };

  const fillAdminCreds = () => {
    setEmail('admin@omnichat.io');
    setPassword('123456');
    setError('');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-slate-50 p-6 font-sans relative overflow-hidden">
      {/* Background Decor - Cool/Neutral Blobs */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] right-[-5%] w-96 h-96 bg-indigo-300/30 rounded-full blur-3xl animate-pulse"></div>
        <div className="absolute bottom-[-10%] left-[-5%] w-96 h-96 bg-teal-300/30 rounded-full blur-3xl animate-pulse" style={{animationDelay: '1s'}}></div>
        <div className="absolute top-[40%] left-[20%] w-40 h-40 bg-purple-200/40 rounded-full blur-2xl"></div>
      </div>

      <div className="max-w-[420px] w-full bg-white/70 backdrop-blur-xl p-10 rounded-[3rem] shadow-[0_20px_60px_-15px_rgba(99,102,241,0.15)] border border-white relative z-10 transition-all hover:scale-[1.01]">
        <div className="text-center mb-10">
          <div className="mx-auto w-20 h-20 bg-gradient-to-br from-indigo-500 to-violet-500 rounded-3xl flex items-center justify-center text-white text-3xl shadow-xl shadow-indigo-300/50 mb-6 transform -rotate-6 hover:rotate-6 transition-transform cursor-pointer border-4 border-white">
            <i className="fa-solid fa-robot"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight mb-2">
            {isRegister ? 'Tạo tài khoản' : 'Chào mừng trở lại!'}
          </h2>
          <p className="text-slate-500 font-bold text-sm">OmniChat - AI Support System</p>
        </div>

        <form className="space-y-6" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-4 rounded-2xl text-sm font-bold flex items-center ${error.includes('thành công') ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-500'}`}>
              <i className={`fa-solid ${error.includes('thành công') ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-3 text-lg`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div className="group">
              <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-4">Email của bạn</label>
              <div className="relative">
                <div className="absolute left-1 top-1 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm text-indigo-400 z-10">
                   <i className="fa-solid fa-envelope"></i>
                </div>
                <input 
                  type="email" 
                  required 
                  value={email} 
                  onChange={(e) => setEmail(e.target.value)} 
                  className="block w-full pl-14 pr-6 py-3.5 bg-white/50 border-2 border-white rounded-full focus:ring-4 focus:ring-indigo-100 focus:border-indigo-300 outline-none text-sm font-bold text-slate-700 placeholder:text-slate-400 shadow-sm transition-all" 
                  placeholder="name@company.com" 
                />
              </div>
            </div>
            <div className="group">
              <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-4">Mật khẩu</label>
              <div className="relative">
                 <div className="absolute left-1 top-1 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm text-indigo-400 z-10">
                   <i className="fa-solid fa-lock"></i>
                </div>
                <input 
                  type="password" 
                  required 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)} 
                  className="block w-full pl-14 pr-6 py-3.5 bg-white/50 border-2 border-white rounded-full focus:ring-4 focus:ring-indigo-100 focus:border-indigo-300 outline-none text-sm font-bold text-slate-700 placeholder:text-slate-400 shadow-sm transition-all" 
                  placeholder="••••••••" 
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-full font-bold text-base shadow-xl shadow-slate-300/40 transform hover:-translate-y-1 transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {isLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào Dashboard')}
            {!isLoading && <i className="fa-solid fa-arrow-right"></i>}
          </button>
        </form>

        {!isRegister && (
          <div className="mt-6 text-center">
            <button 
              type="button"
              onClick={fillAdminCreds}
              className="inline-flex items-center px-5 py-2.5 bg-white hover:bg-indigo-50 text-xs font-bold text-slate-500 hover:text-indigo-600 border border-slate-100 hover:border-indigo-200 rounded-full transition-all shadow-sm hover:shadow-md"
            >
              <i className="fa-solid fa-key mr-2 text-indigo-400"></i>
              Thử Demo: admin@omnichat.io / 123456
            </button>
          </div>
        )}

        <div className="mt-8 pt-6 border-t border-slate-100/50 text-center">
          <p className="text-slate-500 text-sm font-bold">
            {isRegister ? 'Đã có tài khoản?' : 'Chưa có tài khoản?'}
            <button 
              onClick={() => { setIsRegister(!isRegister); setError(''); }} 
              className="ml-2 text-indigo-500 hover:text-indigo-600 font-black hover:underline"
            >
              {isRegister ? 'Đăng nhập' : 'Đăng ký miễn phí'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { View, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  currentView: View;
  onViewChange: (view: View) => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  user: User;
}

const Sidebar: React.FC<Props> = ({ currentView, onViewChange, onLogout, isOpen, onClose, user }) => {
  const isMaster = user.role === 'master';
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(user.id, passwordForm.old, passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const menuItems = [
    { id: View.DASHBOARD, label: 'Tổng quan', icon: 'fa-solid fa-chart-pie' },
    ...(isMaster ? [
      { id: View.CUSTOMER_MANAGEMENT, label: 'Khách hàng', icon: 'fa-solid fa-users-gear' },
      { id: View.CHAT_HISTORY, label: 'Lịch sử hệ thống', icon: 'fa-solid fa-clock-rotate-left' },
    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-comments' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức', icon: 'fa-solid fa-book-open' },
      { id: View.WIDGET_CONFIG, label: 'Làm đẹp Widget', icon: 'fa-solid fa-wand-magic-sparkles' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
    ]),
    { id: View.DEPLOYMENT_GUIDE, label: 'Hướng dẫn', icon: 'fa-solid fa-circle-question' },
  ];

  return (
    <>
    <div className={`
      fixed inset-y-4 left-4 z-50 w-72 bg-white/80 backdrop-blur-xl border border-white rounded-[2.5rem] flex flex-col py-6 transition-all duration-300 lg:relative lg:translate-x-0 shadow-[0_20px_40px_-15px_rgba(0,0,0,0.05)]
      ${isOpen ? 'translate-x-0' : '-translate-x-[110%] lg:translate-x-0'}
    `}>
      <div className="px-8 mb-8 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-12 h-12 ${isMaster ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-violet-500'} rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-200 transform -rotate-6`}>
            <i className={`fa-solid ${isMaster ? 'fa-crown' : 'fa-robot'} text-xl`}></i>
          </div>
          <div>
            <span className="font-extrabold text-xl tracking-tight text-slate-800 block leading-none">OmniChat</span>
            <span className="text-[10px] font-bold text-indigo-500 tracking-widest uppercase">Smart AI</span>
          </div>
        </div>
        <button onClick={onClose} className="lg:hidden w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-indigo-100 hover:text-indigo-500 transition-colors">
          <i className="fa-solid fa-xmark"></i>
        </button>
      </div>

      <nav className="flex-1 px-4 space-y-2 overflow-y-auto no-scrollbar">
        {menuItems.map(item => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={`w-full flex items-center gap-4 px-5 py-4 rounded-[2rem] transition-all duration-300 group relative overflow-hidden ${
              currentView === item.id 
              ? (isMaster ? 'bg-slate-800 text-white shadow-lg shadow-slate-300' : 'bg-gradient-to-r from-indigo-500 to-violet-500 text-white shadow-lg shadow-indigo-200 scale-105')
              : 'text-slate-500 hover:bg-indigo-50 hover:text-indigo-600 font-bold hover:scale-[1.02]'
            }`}
          >
            <i className={`${item.icon} w-6 text-center text-lg ${currentView === item.id ? 'text-white' : 'text-slate-300 group-hover:text-indigo-500 transition-colors'}`}></i>
            <span className="text-sm font-bold">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="px-4 mt-auto">
        {/* Profile Card */}
        <div className="bg-gradient-to-b from-white to-slate-50 border border-white rounded-[2rem] p-5 shadow-sm relative overflow-hidden group">
           <div className="flex items-center gap-3 mb-4">
             <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white font-bold shrink-0 shadow-md border-2 border-white ${isMaster ? 'bg-slate-700' : 'bg-gradient-to-tr from-cyan-400 to-blue-500'}`}>
               {user.email.substring(0, 1).toUpperCase()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-bold text-slate-800 truncate">{isMaster ? 'Master Admin' : 'Doanh nghiệp'}</p>
               <p className="text-xs text-slate-400 truncate font-semibold">{user.email}</p>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-2">
             <button 
                onClick={() => setShowPasswordModal(true)}
                className="col-span-1 text-xs font-bold text-slate-600 hover:text-indigo-600 py-2.5 bg-white hover:bg-indigo-50 rounded-xl transition-all shadow-sm"
              >
                Đổi pass
             </button>
             <button 
               onClick={onLogout}
               className="col-span-1 text-xs font-bold text-rose-500 hover:text-rose-600 py-2.5 bg-rose-50 hover:bg-rose-100 rounded-xl transition-all shadow-sm"
             >
               Thoát
             </button>
           </div>
        </div>
      </div>
    </div>

    {/* Change Password Modal */}
    {showPasswordModal && (
      <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-md z-[100] flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-[0_20px_60px_-15px_rgba(0,0,0,0.1)] w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-300 border border-white">
          <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
             <h3 className="font-bold text-xl text-slate-800">Đổi mật khẩu</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-10 h-10 rounded-full bg-white border border-slate-100 flex items-center justify-center text-slate-400 hover:bg-indigo-50 hover:text-indigo-500 transition-colors">
               <i className="fa-solid fa-xmark"></i>
             </button>
          </div>
          <form onSubmit={handleChangePassword} className="p-8 space-y-5">
             {passwordMsg.text && (
               <div className={`p-4 rounded-2xl text-sm font-bold flex items-center ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                 <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-2 text-lg`}></i>
