                      <h3 className="text-lg font-bold text-slate-800">Không tìm thấy ai hết</h3>
                      <p className="text-sm text-slate-500 mt-2 font-medium">Thử tìm từ khóa khác xem sao nha.</p>
                      <button onClick={loadCustomers} className="mt-4 text-indigo-500 font-bold text-sm hover:underline">
                        Tải lại danh sách
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Reset Password Modal */}
      {resetModal.isOpen && (
        <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-300 border border-white">
             <div className="p-8 text-center">
               <div className="w-20 h-20 bg-amber-100 text-amber-500 rounded-3xl flex items-center justify-center mx-auto mb-5 text-3xl shadow-lg shadow-amber-200 transform rotate-12">
                 <i className="fa-solid fa-key"></i>
               </div>
               <h3 className="text-xl font-black text-slate-800">Reset mật khẩu</h3>
               <p className="text-sm text-slate-500 mt-2 font-medium">
                 Tạo mật khẩu mới cho <span className="font-bold text-slate-900">{resetModal.email}</span>.
               </p>
               <input 
                 type="text" 
                 placeholder="Nhập mật khẩu mới..."
                 className="w-full mt-6 px-6 py-4 bg-slate-50 border-2 border-transparent rounded-2xl text-sm font-bold text-center focus:outline-none focus:bg-white focus:border-amber-300 transition-all"
                 value={newResetPassword}
                 onChange={e => setNewResetPassword(e.target.value)}
               />
               <div className="grid grid-cols-2 gap-3 mt-8">
                 <button onClick={() => setResetModal({ isOpen: false, userId: null, email: '' })} className="py-3.5 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-colors">Hủy nha</button>
                 <button onClick={handleResetPassword} className="py-3.5 bg-amber-500 text-white rounded-2xl font-bold hover:bg-amber-600 transition-colors shadow-lg shadow-amber-200">Xác nhận</button>
               </div>
             </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-300 border border-white">
             <div className="p-8 text-center">
               <div className="w-20 h-20 bg-rose-100 text-rose-500 rounded-3xl flex items-center justify-center mx-auto mb-5 text-3xl shadow-lg shadow-rose-200 transform -rotate-12">
                 <i className="fa-solid fa-trash-can"></i>
               </div>
               <h3 className="text-xl font-black text-slate-800">Xác nhận xóa bé này?</h3>
               <p className="text-sm text-slate-500 mt-2 leading-relaxed font-medium">
                 Tài khoản <span className="font-bold text-slate-900">{deleteModal.email}</span> sẽ bị xóa vĩnh viễn cùng toàn bộ dữ liệu đó nha.
               </p>
               <div className="grid grid-cols-2 gap-3 mt-8">
                 <button onClick={() => setDeleteModal({ isOpen: false, userId: null, email: '' })} className="py-3.5 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-colors">Giữ lại</button>
                 <button onClick={handleDeleteUser} className="py-3.5 bg-rose-500 text-white rounded-2xl font-bold hover:bg-rose-600 transition-colors shadow-lg shadow-rose-200">Xóa luôn</button>
               </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

