import React, { useState } from 'react';
import { View, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  currentView: View;
  onViewChange: (view: View) => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  user: User;
}

const Sidebar: React.FC<Props> = ({ currentView, onViewChange, onLogout, isOpen, onClose, user }) => {
  const isMaster = user.role === 'master';
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(user.id, passwordForm.old, passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const menuItems = [
    { id: View.DASHBOARD, label: 'Tổng quan', icon: 'fa-solid fa-chart-pie' },
    ...(isMaster ? [
      { id: View.CUSTOMER_MANAGEMENT, label: 'Khách hàng', icon: 'fa-solid fa-users-gear' },
      { id: View.CHAT_HISTORY, label: 'Lịch sử hệ thống', icon: 'fa-solid fa-clock-rotate-left' },
    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-comments' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức', icon: 'fa-solid fa-book-open' },
      { id: View.WIDGET_CONFIG, label: 'Làm đẹp Widget', icon: 'fa-solid fa-wand-magic-sparkles' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
    ]),
    { id: View.DEPLOYMENT_GUIDE, label: 'Hướng dẫn', icon: 'fa-solid fa-circle-question' },
  ];

  return (
    <>
    <div className={`
      fixed inset-y-4 left-4 z-50 w-72 bg-white/60 dark:bg-slate-800/60 backdrop-blur-2xl border border-white dark:border-slate-700 rounded-[2.5rem] flex flex-col py-6 transition-all duration-300 lg:relative lg:translate-x-0 shadow-2xl shadow-indigo-100/20 dark:shadow-none
      ${isOpen ? 'translate-x-0' : '-translate-x-[110%] lg:translate-x-0'}
    `}>
      <div className="px-8 mb-8 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-12 h-12 ${isMaster ? 'bg-slate-800 dark:bg-slate-900' : 'bg-gradient-to-tr from-pink-500 to-violet-500'} rounded-2xl flex items-center justify-center text-white shadow-lg shadow-pink-500/30 transform -rotate-6`}>
            <i className={`fa-solid ${isMaster ? 'fa-crown' : 'fa-robot'} text-xl`}></i>
          </div>
          <div>
            <span className="font-extrabold text-xl tracking-tight text-slate-800 dark:text-white block leading-none">OmniChat</span>
            <span className="text-[10px] font-bold text-pink-500 dark:text-pink-400 tracking-widest uppercase">Smart AI</span>
          </div>
        </div>
        <button onClick={onClose} className="lg:hidden w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-slate-500 dark:text-slate-300 hover:bg-pink-100 dark:hover:bg-slate-600 hover:text-pink-500 transition-colors">
          <i className="fa-solid fa-xmark"></i>
        </button>
      </div>

      <nav className="flex-1 px-4 space-y-2 overflow-y-auto no-scrollbar">
        {menuItems.map(item => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={`w-full flex items-center gap-4 px-5 py-4 rounded-[2rem] transition-all duration-300 group relative overflow-hidden ${
              currentView === item.id 
              ? (isMaster ? 'bg-slate-800 text-white shadow-lg shadow-slate-500/50' : 'bg-gradient-to-r from-violet-500 to-fuchsia-500 text-white shadow-lg shadow-violet-500/40 scale-105')
              : 'text-slate-500 dark:text-slate-400 hover:bg-white/50 dark:hover:bg-slate-700/50 hover:text-violet-600 dark:hover:text-violet-400 font-bold hover:scale-[1.02]'
            }`}
          >
            <i className={`${item.icon} w-6 text-center text-lg ${currentView === item.id ? 'text-white' : 'text-slate-300 dark:text-slate-500 group-hover:text-violet-500 dark:group-hover:text-violet-400 transition-colors'}`}></i>
            <span className="text-sm font-bold">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="px-4 mt-auto">
        {/* Profile Card */}
        <div className="bg-gradient-to-b from-white/50 to-white/80 dark:from-slate-700/50 dark:to-slate-700/80 border border-white dark:border-slate-600 rounded-[2rem] p-5 shadow-sm relative overflow-hidden group backdrop-blur-sm">
           <div className="flex items-center gap-3 mb-4">
             <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white font-bold shrink-0 shadow-md border-2 border-white dark:border-slate-600 ${isMaster ? 'bg-slate-700' : 'bg-gradient-to-tr from-cyan-400 to-blue-500'}`}>
               {user.email.substring(0, 1).toUpperCase()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-bold text-slate-800 dark:text-white truncate">{isMaster ? 'Master Admin' : 'Doanh nghiệp'}</p>
               <p className="text-xs text-slate-400 dark:text-slate-400 truncate font-semibold">{user.email}</p>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-2">
             <button 
                onClick={() => setShowPasswordModal(true)}
                className="col-span-1 text-xs font-bold text-slate-600 dark:text-slate-300 hover:text-violet-600 dark:hover:text-violet-400 py-2.5 bg-white dark:bg-slate-800 hover:bg-violet-50 dark:hover:bg-slate-600 rounded-xl transition-all shadow-sm"
              >
                Đổi pass
             </button>
             <button 
               onClick={onLogout}
               className="col-span-1 text-xs font-bold text-rose-500 hover:text-rose-600 py-2.5 bg-rose-50 dark:bg-rose-900/30 hover:bg-rose-100 dark:hover:bg-rose-900/50 rounded-xl transition-all shadow-sm"
             >
               Thoát
             </button>
           </div>
        </div>
      </div>
    </div>

    {/* Change Password Modal */}
    {showPasswordModal && (
      <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[100] flex items-center justify-center p-4">
        <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-[0_20px_60px_-15px_rgba(0,0,0,0.1)] w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-300 border border-white dark:border-slate-700">
          <div className="p-8 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800">
             <h3 className="font-bold text-xl text-slate-800 dark:text-white">Đổi mật khẩu</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-10 h-10 rounded-full bg-white dark:bg-slate-700 border border-slate-100 dark:border-slate-600 flex items-center justify-center text-slate-400 hover:bg-pink-50 dark:hover:bg-slate-600 hover:text-pink-500 transition-colors">
               <i className="fa-solid fa-xmark"></i>
             </button>
          </div>
          <form onSubmit={handleChangePassword} className="p-8 space-y-5">
             {passwordMsg.text && (
               <div className={`p-4 rounded-2xl text-sm font-bold flex items-center ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                 <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-2 text-lg`}></i>
                 {passwordMsg.text}
               </div>
             )}

             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Mật khẩu hiện tại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-violet-300 dark:focus:border-violet-500 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white dark:focus:bg-slate-800 transition-all text-slate-700 dark:text-slate-200 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-violet-300 dark:focus:border-violet-500 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white dark:focus:bg-slate-800 transition-all text-slate-700 dark:text-slate-200 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Xác nhận lại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-violet-300 dark:focus:border-violet-500 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white dark:focus:bg-slate-800 transition-all text-slate-700 dark:text-slate-200 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.confirm}
                 onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
               />
             </div>

             <button type="submit" className="w-full py-4 bg-slate-800 dark:bg-violet-600 hover:bg-slate-900 dark:hover:bg-violet-700 text-white rounded-2xl font-bold shadow-lg shadow-slate-300 dark:shadow-violet-900/30 transition-all active:scale-[0.98] mt-2">
