import React, { useState } from 'react';
import { apiService } from '../services/apiService';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      let result;
      if (isRegister) {
        result = await apiService.register(email, password);
      } else {
        result = await apiService.login(email, password);
      }

      if (result.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Đăng nhập đi nè.');
        } else {
          onLogin(result.user);
        }
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Huhu, có lỗi gì đó rồi.');
    } finally {
      setIsLoading(false);
    }
  };

  const fillAdminCreds = () => {
    setEmail('admin@omnichat.io');
    setPassword('123456');
    setError('');
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#f0f2f5] p-6 font-sans relative overflow-hidden">
      {/* Background Decor - Vibrant Mesh */}
      <div className="absolute inset-0 z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] bg-purple-400 rounded-full mix-blend-multiply filter blur-[100px] opacity-40 animate-blob"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-400 rounded-full mix-blend-multiply filter blur-[100px] opacity-40 animate-blob animation-delay-2000"></div>
         <div className="absolute top-[40%] left-[40%] w-[400px] h-[400px] bg-pink-400 rounded-full mix-blend-multiply filter blur-[100px] opacity-40 animate-blob animation-delay-4000"></div>
      </div>

      <div className="max-w-[420px] w-full bg-white/60 backdrop-blur-xl p-10 rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-white/50 relative z-10 transition-all hover:scale-[1.01]">
        <div className="text-center mb-10">
          <div className="mx-auto w-20 h-20 bg-gradient-to-br from-violet-500 to-fuchsia-500 rounded-3xl flex items-center justify-center text-white text-3xl shadow-xl shadow-fuchsia-300/50 mb-6 transform -rotate-6 hover:rotate-6 transition-transform cursor-pointer border-4 border-white">
            <i className="fa-solid fa-robot"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight mb-2">
            {isRegister ? 'Tạo tài khoản' : 'Chào mừng trở lại!'}
          </h2>
          <p className="text-slate-500 font-bold text-sm">OmniChat - AI Support System</p>
        </div>

        <form className="space-y-6" onSubmit={handleSubmit}>
          {error && (
