              onClick={() => { setIsRegister(!isRegister); setError(''); }} 
              className="ml-2 text-violet-500 hover:text-violet-600 font-black hover:underline"
            >
              {isRegister ? 'Đăng nhập' : 'Đăng ký miễn phí'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

