import React, { useState } from 'react';
import { View, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  currentView: View;
  onViewChange: (view: View) => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  user: User;
}

const Sidebar: React.FC<Props> = ({ currentView, onViewChange, onLogout, isOpen, onClose, user }) => {
  const isMaster = user.role === 'master';
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(user.id, passwordForm.old, passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const menuItems = [
    { id: View.DASHBOARD, label: 'Tổng quan', icon: 'fa-solid fa-chart-pie' },
    ...(isMaster ? [
      { id: View.CUSTOMER_MANAGEMENT, label: 'Quản lý Khách hàng', icon: 'fa-solid fa-users-gear' },
      { id: View.CHAT_HISTORY, label: 'Lịch sử Hệ thống', icon: 'fa-solid fa-clock-rotate-left' },
    ] : [
      { id: View.CHAT_HISTORY, label: 'Lịch sử Chat', icon: 'fa-solid fa-comments' },
      { id: View.KNOWLEDGE_BASE, label: 'Kho tri thức', icon: 'fa-solid fa-book-open' },
      { id: View.WIDGET_CONFIG, label: 'Làm đẹp Widget', icon: 'fa-solid fa-wand-magic-sparkles' },
      { id: View.INTEGRATION, label: 'Mã nhúng', icon: 'fa-solid fa-code' },
    ]),
    { id: View.DEPLOYMENT_GUIDE, label: 'Hướng dẫn', icon: 'fa-solid fa-circle-question' },
  ];

  return (
    <>
    <div className={`
      fixed inset-y-4 left-4 z-50 w-80 bg-white/95 dark:bg-slate-800/95 backdrop-blur-xl border border-white dark:border-slate-700 rounded-[2.5rem] flex flex-col py-8 transition-all duration-300 lg:relative lg:translate-x-0 shadow-2xl shadow-indigo-200/40 dark:shadow-none
      ${isOpen ? 'translate-x-0' : '-translate-x-[110%] lg:translate-x-0'}
    `}>
      <div className="px-8 mb-10 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className={`w-14 h-14 ${isMaster ? 'bg-gradient-to-br from-indigo-500 to-purple-600' : 'bg-gradient-to-tr from-pink-500 to-rose-500'} rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-300/50 dark:shadow-none transform -rotate-3 hover:rotate-0 transition-transform`}>
            <i className={`fa-solid ${isMaster ? 'fa-crown' : 'fa-robot'} text-2xl`}></i>
          </div>
          <div>
            <span className="font-extrabold text-2xl tracking-tight text-slate-800 dark:text-white block leading-none mb-1">OmniChat</span>
            <span className={`text-xs font-bold ${isMaster ? 'text-indigo-500' : 'text-pink-500'} tracking-widest uppercase`}>
              {isMaster ? 'Master Admin' : 'Smart AI'}
            </span>
          </div>
        </div>
        <button onClick={onClose} className="lg:hidden w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-slate-500 hover:text-pink-500 transition-colors">
          <i className="fa-solid fa-xmark text-lg"></i>
        </button>
      </div>

      <nav className="flex-1 px-6 space-y-3 overflow-y-auto no-scrollbar">
        {menuItems.map(item => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={`w-full flex items-center gap-5 px-6 py-5 rounded-[2rem] transition-all duration-300 group relative overflow-hidden ${
              currentView === item.id 
              ? (isMaster 
                  ? 'bg-gradient-to-r from-indigo-600 to-violet-600 text-white shadow-lg shadow-indigo-500/30 ring-2 ring-indigo-200 dark:ring-indigo-900 scale-[1.03]' 
                  : 'bg-gradient-to-r from-pink-500 to-rose-500 text-white shadow-lg shadow-pink-500/30 ring-2 ring-pink-200 dark:ring-pink-900 scale-[1.03]')
              : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700/60 hover:text-indigo-600 dark:hover:text-indigo-300 font-bold hover:scale-[1.02]'
            }`}
          >
            <i className={`${item.icon} w-6 text-center text-xl ${currentView === item.id ? 'text-white' : 'text-slate-400 dark:text-slate-500 group-hover:text-current transition-colors'}`}></i>
            <span className="text-base font-bold tracking-wide">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="px-6 mt-8">
        {/* Profile Card */}
        <div className="bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 rounded-[2rem] p-5 shadow-sm relative overflow-hidden group">
           <div className="flex items-center gap-4 mb-4">
             <div className={`w-14 h-14 rounded-full flex items-center justify-center text-white text-xl font-bold shrink-0 shadow-md border-4 border-white dark:border-slate-600 ${isMaster ? 'bg-gradient-to-tr from-slate-700 to-slate-900' : 'bg-gradient-to-tr from-cyan-400 to-blue-500'}`}>
               {user.email.substring(0, 1).toUpperCase()}
             </div>
             <div className="overflow-hidden min-w-0">
               <p className="text-sm font-extrabold text-slate-800 dark:text-white truncate">{isMaster ? 'Administrator' : 'Doanh nghiệp'}</p>
               <p className="text-xs text-slate-500 dark:text-slate-400 truncate font-bold">{user.email}</p>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-3">
             <button 
                onClick={() => setShowPasswordModal(true)}
                className="col-span-1 text-xs font-bold text-slate-600 dark:text-slate-300 hover:text-indigo-600 dark:hover:text-indigo-400 py-3 bg-slate-50 dark:bg-slate-800 hover:bg-indigo-50 dark:hover:bg-slate-600 rounded-2xl transition-all"
              >
                Đổi pass
             </button>
             <button 
               onClick={onLogout}
               className="col-span-1 text-xs font-bold text-rose-500 hover:text-rose-600 py-3 bg-rose-50 dark:bg-rose-900/20 hover:bg-rose-100 dark:hover:bg-rose-900/40 rounded-2xl transition-all"
             >
               Thoát
             </button>
           </div>
        </div>
      </div>
    </div>

    {/* Change Password Modal */}
    {showPasswordModal && (
      <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[100] flex items-center justify-center p-4">
        <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-300 border-4 border-white dark:border-slate-700">
          <div className="p-8 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-800">
             <h3 className="font-bold text-xl text-slate-800 dark:text-white">Đổi mật khẩu</h3>
             <button onClick={() => setShowPasswordModal(false)} className="w-10 h-10 rounded-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 flex items-center justify-center text-slate-500 hover:bg-rose-50 hover:text-rose-500 transition-colors">
               <i className="fa-solid fa-xmark"></i>
             </button>
          </div>
          <form onSubmit={handleChangePassword} className="p-8 space-y-5">
             {passwordMsg.text && (
               <div className={`p-4 rounded-2xl text-sm font-bold flex items-center ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200' : 'bg-rose-50 text-rose-600 border border-rose-200'}`}>
                 <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-2 text-lg`}></i>
                 {passwordMsg.text}
               </div>
             )}

             <div>
               <label className="block text-xs font-extrabold text-slate-500 uppercase mb-2 ml-1">Mật khẩu hiện tại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 focus:border-indigo-500 rounded-2xl text-sm font-bold focus:outline-none transition-all text-slate-700 dark:text-slate-200 placeholder-slate-400"
                 placeholder="••••••"
                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-extrabold text-slate-500 uppercase mb-2 ml-1">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 focus:border-indigo-500 rounded-2xl text-sm font-bold focus:outline-none transition-all text-slate-700 dark:text-slate-200 placeholder-slate-400"
                 placeholder="••••••"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-extrabold text-slate-500 uppercase mb-2 ml-1">Xác nhận lại</label>
