              <div className="relative">
                 <div className="absolute left-2 top-2 w-10 h-10 bg-violet-50 rounded-full flex items-center justify-center text-violet-600 z-10 border border-violet-100">
                   <i className="fa-solid fa-lock"></i>
                </div>
                <input 
                  type="password" 
                  required 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)} 
                  className="block w-full pl-14 pr-6 py-4 bg-white border-2 border-slate-200 rounded-2xl focus:ring-4 focus:ring-violet-100 focus:border-violet-500 outline-none text-base font-bold text-slate-800 placeholder:text-slate-400 transition-all" 
                  placeholder="••••••••" 
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full py-4 bg-gradient-to-r from-violet-600 to-fuchsia-600 hover:from-violet-700 hover:to-fuchsia-700 text-white rounded-2xl font-bold text-lg shadow-xl shadow-fuchsia-300/40 transform hover:-translate-y-1 transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-3 mt-4"
