            {isLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký ngay' : 'Vào Dashboard')}
            {!isLoading && <i className="fa-solid fa-arrow-right"></i>}
          </button>
        </form>

        {!isRegister && (
          <div className="mt-8 text-center">
            <button 
              type="button"
              onClick={fillAdminCreds}
              className="inline-flex items-center px-6 py-3 bg-slate-50 hover:bg-violet-50 text-sm font-bold text-slate-600 hover:text-violet-700 border-2 border-slate-200 hover:border-violet-200 rounded-2xl transition-all shadow-sm hover:shadow-md"
            >
              <i className="fa-solid fa-key mr-2 text-violet-500"></i>
              Thử Demo Admin
            </button>
          </div>
        )}

        <div className="mt-8 pt-6 border-t border-slate-100 text-center">
          <p className="text-slate-500 text-sm font-bold">
            {isRegister ? 'Đã có tài khoản?' : 'Chưa có tài khoản?'}
            <button 
              onClick={() => { setIsRegister(!isRegister); setError(''); }} 
              className="ml-2 text-violet-600 hover:text-violet-700 font-black hover:underline"
            >
              {isRegister ? 'Đăng nhập' : 'Đăng ký miễn phí'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

