            </div>
            <div className="text-[10px] text-center text-slate-400 mt-2 font-bold flex items-center justify-center gap-1">
              <i className="fa-solid fa-bolt text-amber-400"></i> by BibiChat AI
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

